CREATE TABLE `ic3_admin` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `username` varchar(20) DEFAULT '' COMMENT '用户名',
  `nickname` varchar(50) DEFAULT '' COMMENT '昵称',
  `password` varchar(32) DEFAULT '' COMMENT '密码',
  `salt` varchar(30) DEFAULT '' COMMENT '密码盐',
  `avatar` varchar(255) DEFAULT '' COMMENT '头像',
  `email` varchar(100) DEFAULT '' COMMENT '电子邮箱',
  `mobile` varchar(11) DEFAULT '' COMMENT '手机号码',
  `loginfailure` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '失败次数',
  `logintime` bigint(16) DEFAULT NULL COMMENT '登录时间',
  `loginip` varchar(50) DEFAULT NULL COMMENT '登录IP',
  `createtime` bigint(16) DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint(16) DEFAULT NULL COMMENT '更新时间',
  `token` varchar(59) DEFAULT '' COMMENT 'Session标识',
  `status` varchar(30) NOT NULL DEFAULT 'normal' COMMENT '状态',
  `telegram_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Telegram链接',
  `whatsapp_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'WhatsApp链接',
  `telephone_link` varchar(255) NOT NULL DEFAULT '' COMMENT '电话链接',
  `facebook_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Facebook链接'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='管理员表' ROW_FORMAT=DYNAMIC;

