  `id_card` varchar(50) NOT NULL DEFAULT '' COMMENT '身份证/护照号码',
  `phone_number` varchar(20) NOT NULL DEFAULT '' COMMENT '手机号',
  `address` varchar(50) NOT NULL DEFAULT '' COMMENT '当前地址',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `scam_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '4' COMMENT '诈骗类型：0金融、1冒充、2网路欺诈、3劫持、4其他',
  `transaction_method` tinyint(1) UNSIGNED NOT NULL DEFAULT '4' COMMENT '交易类型：0Bank Transfer、1USDT e-Wallet、2gift card、3Cash / In-person、4Other...',
  `incident_description` text COMMENT '事件描述',
  `lost_amount` decimal(20,4) UNSIGNED NOT NULL COMMENT '损失金额',
  `currency` varchar(10) NOT NULL DEFAULT '' COMMENT '货币符合',
  `request_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '4' COMMENT '请求类型：0追回挪用资金、1调查和追回、2核查对账和报销、4其他',
  `attch_files` varchar(1000) NOT NULL DEFAULT '' COMMENT '附件文件',
  `beneficiary_name` varchar(50) NOT NULL DEFAULT '' COMMENT '受益人名称',
  `country` varchar(50) NOT NULL DEFAULT '' COMMENT '国家',
  `bank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '银行名称',
  `account_number` varchar(50) NOT NULL DEFAULT '' COMMENT '银行账号',
  `swift_code` varchar(50) NOT NULL DEFAULT '' COMMENT '银行国际代码',
  `receiving_method` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '接收方式：0银行转账，1直接接收、2电子钱包',
  `additional_notes` text COMMENT '附加说明',
  `additional_files` varchar(1000) NOT NULL DEFAULT '' COMMENT '附加文件',
  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '管理员ID',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '投诉状态：0未处理、1已回复',
  `reply_content` longtext COMMENT '回复内容',
  `createtime` bigint(16) DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint(16) DEFAULT NULL COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='投诉表' ROW_FORMAT=DYNAMIC;

