(248, 1, 'admin', '/mHrEfCViOs.php/psa/psa/add?dialog=1', 'Public Service Announcements / PSA数据管理 / 添加', '{\"dialog\":\"1\",\"lang\":\"zh-cn\",\"row\":{\"title\":\"ABA Foundation and FBI Release New Infographic to Help Americans Spot and Avoid Deepfake Scams\",\"content\":\"You are now leaving IC3.gov to visit:https:\\/\\/www.aba.com\\/about-us\\/press-room\\/press-releases\\/ABA-Foundation-and-FBI-Joint-Infographic-on-Deepfake-ScamsThe IC3 may not endorse the organizations or views represented by non-FBI sites and takes no responsibility for, and exercises no control over the accuracy, accessibility, copyright or trademark compliance, or legality of the material contained on this site.Thank you for visiting our site.Return to top\",\"publish_date\":\"2025-09-04\",\"file_zh\":\"\",\"file_tw\":\"\"}}', '38.252.150.233', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 1766501144),
