(467, 1, 'admin', '/mHrEfCViOs.php/complaint/complaint/edit/ids/12?dialog=1', 'Complaint / 投诉管理 / 编辑', '{\"dialog\":\"1\",\"lang\":\"zh-cn\",\"row\":{\"user_id\":\"23\",\"is_affected\":\"0\",\"full_name\":\"Mã Vĩnh Trinh\",\"date_birth\":\"1975-12-23\",\"gender\":\"0\",\"nationality\":\"Canada\",\"phone_number\":\"12023442628\",\"address\":\"\",\"email\":\"nakjgf@gmail.com\",\"scam_type\":\"0\",\"transaction_method\":\"0\",\"incident_description\":\"Snakhhbghjijbvffgh\",\"lost_amount\":\"109009.0000\",\"currency\":\"Cad\",\"request_type\":\"0\",\"attch_files\":\"\",\"beneficiary_name\":\"Mã vĩnh trinh\",\"country\":\"\",\"swift_code\":\"\",\"receiving_method\":\"0\",\"additional_notes\":\"\",\"additional_files\":\"\",\"status\":\"1\",\"reply_content\":\"&amp;nbsp; &amp;nbsp; &amp;nbsp;LƯƠNG + HOA HỒNG ( 301 ) &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;THỜI GIAN LÀM VIỆC TẠI VĂN PHÒNG 301 TỪ LÚC &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;21:00&amp;nbsp;đến 23:30 &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;00:15 đến 03:00&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;04:30 đến 09:30&amp;nbsp;Tiền cơm sẽ được phát 2 lần của tháng vào ngày 1 đến 3 &amp;nbsp;tây và ngày 16 đến 18 tây mỗi lần nhận 2.400k &amp;nbsp;Lương cơ bản của tất cả nhân viên sale cố định sẽ là 20.000k bất kể người mới vào hoặc đã làm lâu vẫn sẽ được tính lương cơ bản 20.000k (Trong tháng nhân viên xin off bệnh hay có công việc gấp gia đình sẽ được xem xét cho off nhiều nhất 2 buồi không trừ lương , nhưng sẽ bị mất chuyên cần .)&amp;nbsp;Hoa hồng + thưởng áp dụng từ tháng 01\\/12\\/2025 &amp;nbsp;Phần trăm hoa hồng của doanh thu cá nhân 250.000.000 VND&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;3%Trên 500.000.000 VND&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;6% Trên 850.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;7%1.000.000.000 VND &amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;10%2.500.000.000 VND&amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;12%5.000.000.000 VND &amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;15%10.000.000.000 VND&amp;gt;&amp;gt;&amp;gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;20%&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;TIỀN THƯỞNG NẠP MỘT LẦN &amp;nbsp;Trên 20.000.000 VND&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;200K50.000.000 VND&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;500K100.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;2.000K200.000.000 VND&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;3.000K500.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;10.000K 800.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;15.000K2.000.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;30.000K&amp;nbsp;&amp;nbsp;TÍCH LŨY NGÀY &amp;nbsp;150.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;1.000K250.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;3.000K350.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;5.000K600.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;7.000K 1.000.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;20.000K3.000.000.000 VND &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;50.000K&amp;nbsp;TRONG THÁNG NHÂN VIÊN ĐẠT MÓC DOANH THU 500 TRIỆU&amp;nbsp;TRỞ&amp;nbsp;LÊN&amp;nbsp;&amp;nbsp;, THÁNG SAU VẪN ĐẠT MÓC 500 TRIỆU TRỞ LÊN THÌ SẼ TĂNG THÊM 3 TRIỆU TIỀN LƯƠNG TRONG THÁNG ĐÓ (TẤT 23 TRIỆU) , THÁNG SAU VẪN ĐẠT MÓC 500 TRIỆU ĐƯỢC CÔNG THÊM 3 TRIỆU( TẤT 26 TRIỆU ) , CAO NHẤT TĂNG LƯƠNG ĐẾN 50 TRIỆU , &amp;nbsp;1 THÁNG KHÔNG ĐẠT SẼ TRỞ LẠI LƯƠNG CƠ BẢN 20 TRIỆU . &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;301 NỘI QUY &amp;nbsp;1.&amp;nbsp;Thời gian làm việc từ 21h00 đến 9h30 đi làm muộn 1 phút -200k cứ thế nhân lên.&amp;nbsp;2.&amp;nbsp;Thời gian đi lấy đồ từ 10h30 đến 00h00 ca 2 từ 5h30 đến 8h00 kể cả thời gian ăn uống.&amp;nbsp;3.&amp;nbsp;&amp;nbsp;Trong giờ làm việc không tự ý về phòng khi chưa thông báo phạt 1.000k &amp;nbsp;4.&amp;nbsp;Nghiêm cấm sử dụng chất kích thích ảnh hưởng đến công việc làm không hiệu quả , những ai sử dụng chất kích thích tuồng khách , tiết lộ thông tin khách ra ngoài và lấy tiền của công ty xử lý phạt theo quy định của sếp.&amp;nbsp;5.&amp;nbsp;Chốt mess khácch hàng tin nhắn để lâu quá 10 phút sẽ bị xử lý phạt 100k lần đầu lần thứ 2 cứ thế nhân lên .&amp;nbsp;6.&amp;nbsp;Trong tháng nhân viên vi phạm bị xử lý phạt 3 lần cuối tháng TT đưa xuống sân chạy 1 vòng sân &amp;nbsp;7.&amp;nbsp;Không dược tự ý chụp ảnh người khác khi không có sự cho phép , nếu có hành vi cố tình với bất cứ mục đích gì đều xử phạt -20.000k &amp;nbsp;8.&amp;nbsp;Trong giờ làm việc phải nghiêm túc , không được đùa giỡn , khiêu khích , đánh nhau , vi phạm nhẹ phạt 2.000k cảnh cáo , nặng phạt 10.000k , lần 2 nhân lên , vẫn tái phạm sa thải đền bù theo công ty&amp;nbsp;9.&amp;nbsp;Tôn trọng cấp trên làm theo mọi chỉ thị nhiệm vụ đưa xuống , hoàn thành sớm nhất theo yêu cầu , không được chống đối &amp;nbsp;, đó là hành vi nghiêm trọng nhất , sẽ đưa lên công ty xử phạt nặng &amp;nbsp;&amp;nbsp;10.&amp;nbsp;Điên thoại cá nhân đặt đúng nơi quy định và bật chế độ yên lặng , điện thoại công việc tan ca phải để đúng nơi quy định , ai vi phạm phạt 100k , lần thứ 2 nhân lên . Không được tự ý sử dụng điện thoại cá nhân trong giờ làm việc , không đăng nhập bất kỳ tài khoản cá nhân nào vào vi tính hay điện thoại công ty , nếu phàt hiện sẽ phạt 1.000 usd đến 5.000 usd &amp;nbsp;11.&amp;nbsp;Trong giờ làm việc không được phép xem video phát hiện mỗi lần xư phạt 200k 12.&amp;nbsp;Mọi vấn đề liên quan đều phải được xử lý từ dưới lên trên nếu tự ý vượt cấp không thông qua từng cấp bật coi như vượt cấp xử lý phạt 500k &amp;nbsp;&amp;nbsp;13.&amp;nbsp;Tự ý nghĩ phép không thông báo cấp trên xem như kháng công 1 ngày &amp;nbsp;14.&amp;nbsp;Những vật liệu tài nguyên do công ty cung cấp tuyệt đối không được thay đổi hoặc tự ý thoát ra ngoài nếu không báo lên và không có lý do chính đáng sẽ bị xử phạt nghiêm khắc 1000$ lần tái phạm x2 đồng thời xa thải.&amp;nbsp;- NHỮNG NỘI QUY TRÊN ÁP DỤNG VÀO 01\\/11\\/2025 MONG MỌI NGƯỜI HỢP TÁC. &amp;nbsp;3 PHẦN THƯỞNG DÀNH CHO NHÂN VIÊN ĐẠT MÓC DOANH THU 2 TỶ ĐẦU TIÊN &amp;nbsp;NGƯỜI ĐẦU TIÊN ĐẠT MÓC 2 TỶ THƯỞNG 1 IPHONE 17 PROMAX &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;NGƯỜI THỨ 2 ĐẠT MÓC 2 TỶ THƯỞNG 1 CHỈ VÀNG 9999&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;NGƯỜI THỨ 3 ĐẠT MÓC 2 TỶ THƯỞNG TIỀN MẶT 500 USD&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;TRONG THÁNG ĐẠT MÓC 2 TỶ, &amp;nbsp;CHỈ ĐƯỢC PHÉP NHẬN 1 PHẦN THƯỞNG&amp;nbsp;\"},\"ids\":\"12\"}', '103.68.47.106', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36', 1766687065),
