INSERT INTO `ic3_psa` (`id`, `code`, `title`, `content`, `publish_year`, `publish_date`, `file_zh`, `file_tw`, `createtime`, `updatetime`) VALUES
(1, 'PSA251113', 'Criminals Impersonate US Health Insurance Providers and Chinese Law Enforcement to Target Chinese Speakers Residing in the United States', '<p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) warns the public about an evolving financial fraud scheme targeting Chinese speaking individuals residing in the United States in which criminals impersonate US health insurance providers and Chinese law enforcement.</p><p>Targeted individuals receive a call from a spoofed telephone number of a legitimate US health insurance provider’s claims department. The call is conducted in Chinese, and the recipient is asked about recent insurance claims for alleged surgical procedures. The criminal then shows the recipient fraudulent invoices on screen via video communication software and demands payment. If the recipient denies having filed the claim or that the procedure took place, the criminal transfers the recipient to someone purporting to be Chinese law enforcement. The law enforcement impersonator then asks for personal identifying information, threatens the individual with extradition or foreign prosecution, and demands a large payment for bail. The impersonator may instruct the victim to download video communication software and maintain connectivity for 24-hour surveillance.</p><section>\r\n    <h2>Tips on How to Protect Yourself</h2>\r\n    <ul>\r\n        <li>Independently verify your health insurance claim records through the health insurance website or customer service phone number.</li>\r\n        <li>Do not share any personal information, including health insurance website login information, with an unsolicited caller.</li>\r\n        <li>Do not wire any money to an unsolicited caller.</li>\r\n        <li>Do not allow anyone to gain control of your computer or maintain connectivity for video surveillance.</li>\r\n    </ul>\r\n</section><section>\r\n    <h2>Report It</h2>\r\n    <p>If you or anyone you know has fallen victim to this impersonation scam, file a complaint with the IC3 at <a href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include any available information including:</p>\r\n    <ul>\r\n        <li>Emails, phone numbers, domains, and company names.</li>\r\n        <li>Transaction or account information even if no funds were lost.</li>\r\n        <li>Details regarding the interaction with the scammers.</li>\r\n    </ul>\r\n</section>', 2025, '2025-11-13', '/uploads/20251121/aaa97963c931cf16d8bb70596d04f6c4.pdf', '', 1762963200, 1763655125),
(3, 'PSA250919', 'Threat Actors Spoofing the FBI IC3 Website for Possible Malicious Activity', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is providing this Public Service Announcement (<abbr>PSA</abbr>) to warn that threat actors are spoofing the FBI Internet Crime Complaint Center (<abbr>IC3</abbr>) government website. A spoofed website is designed to impersonate a legitimate website and may be used for illegal conduct, such as personal information theft and to facilitate monetary scams. Threat actors create spoofed websites often by slightly altering characteristics of legitimate website domains, with the purpose of gathering personally identifiable information entered by a user into the site, including name, home address, phone number, email address, and banking information. For example, spoofed website domains may feature alternate spellings of words or use an alternative top-level domain to impersonate a legitimate website. Members of the public could unknowingly visit spoofed websites while attempting to find FBI IC3\'s website to submit an IC3 report.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><p>The FBI recommends individuals take the following precautions:</p><ul><li>When navigating to IC3\'s official website, type www.ic3.gov directly into the address bar located at the top of your Internet browser, rather than using a search engine.</li><li style=\"margin-top: 0.5rem;\">If using a search engine, avoid any \"sponsored\" results as these are usually paid imitators looking to deter traffic from the legitimate IC3 website.</li><li style=\"margin-top: 0.5rem;\">Verify that the URL of the IC3 website ends in [.]gov and is correctly entered as www.ic3.gov.</li><li style=\"margin-top: 0.5rem;\">Avoid clicking on any link whose URL differs from the legitimate IC3 site to mitigate risk of fraud.</li><li style=\"margin-top: 0.5rem;\">Never click on links that may include suspicious artifacts or graphics, such as unprofessional or low-quality graphics used to imitate a legitimate website</li><li style=\"margin-top: 0.5rem;\">Never share sensitive information if you are unsure of the website\'s legitimacy.</li><li style=\"margin-top: 0.5rem;\">Report any incidents to the legitimate FBI IC3 website only at www.ic3.gov.</li><li style=\"margin-top: 0.5rem;\">IC3 will never ask for payment to recover lost funds, nor will IC3 refer someone to a company requesting payment for recovering funds.</li><li style=\"margin-top: 0.5rem;\">IC3 does not maintain any social media presence.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>The FBI requests potential victims report any interactions with websites or individuals impersonating IC3 to your local FBI Field Office or IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</p><ul><li>Identify information about the person or company that contacted you.</li><li style=\"margin-top: 0.5rem;\">Note the methods of communication used, including websites, emails, and telephone numbers.</li><li style=\"margin-top: 0.5rem;\">Financial transaction information such as date, type of payment, amount, account numbers involved, the name and address of the receiving financial institution, and receiving cryptocurrency addresses.</li><li style=\"margin-top: 0.5rem;\">Description of your interaction with the individual, including how contact was initiated, purpose of the request for money, how you were instructed to make payment, what information you provided, and any other details pertinent to your complaint.</li></ul></section><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">For additional information on similar scams, please see previous Public Service Announcements:</p><ul style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><li>IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2025/PSA250418\">FBI Warns of Scammers Impersonating the IC3</a>\"</li><li style=\"margin-top: 0.5rem;\">IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2022/PSA220307\">FBI Warns of the Impersonation of Law Enforcement and Government Officials</a>\"</li><li style=\"margin-top: 0.5rem;\">IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2022/PSA221110\">Scammers Using Computer-Technical Support Impersonation Scams to Target Victims and Conduct Wire Transfers</a>\"</li></ul>', 2025, '2025-09-19', '', '', 1758211200, 1766499881),
(4, 'PSA250904', 'ABA Foundation and FBI Release New Infographic to Help Americans Spot and Avoid Deepfake Scams', '<main id=\"main-content\" class=\"usa-prose grid-container\" style=\"box-sizing: inherit; font-family: &quot;Source Sans Pro Web&quot;, &quot;Helvetica Neue&quot;, Helvetica, Roboto, Arial, sans-serif; font-size: 1.06rem; line-height: 1.5; margin-left: auto; margin-right: auto; max-width: 64rem; padding-left: 2rem; padding-right: 2rem; border-top: none; color: rgb(27, 27, 27);\"><h4 class=\"padding-top-2\" style=\"box-sizing: inherit; padding-top: 1rem; margin-bottom: 0px; margin-top: 0px; clear: both; font-family: &quot;Merriweather Web&quot;, Georgia, Cambria, &quot;Times New Roman&quot;, Times, serif; font-size: 0.98rem; line-height: 1.2; font-weight: 700;\">You are now leaving IC3.gov to visit:</h4><div class=\"margin-top-2 margin-bottom-2 text-center\" style=\"box-sizing: inherit; margin-top: 1rem; margin-bottom: 1rem;\"><a href=\"https://www.aba.com/about-us/press-room/press-releases/ABA-Foundation-and-FBI-Joint-Infographic-on-Deepfake-Scams\" target=\"_blank\" style=\"box-sizing: inherit;\">https://www.aba.com/about-us/press-room/press-releases/ABA-Foundation-and-FBI-Joint-Infographic-on-Deepfake-Scams</a></div><aside class=\"usa-alert usa-alert--info\" style=\"box-sizing: inherit; margin-top: 1rem; margin-bottom: 0px; background-color: rgb(231, 246, 248); border-left: 0.5rem solid rgb(0, 189, 227);\"><div class=\"usa-alert__body\" style=\"box-sizing: inherit; font-size: 1.06rem; line-height: 1.5; margin-left: auto; margin-right: auto; max-width: 64rem; padding: 1rem 4rem; position: relative;\"><p class=\"usa-alert__text\" style=\"box-sizing: inherit; margin-bottom: 0px; padding-bottom: 0px; padding-top: 0px;\">The IC3 may not endorse the organizations or views represented by non-FBI sites and takes no responsibility for, and exercises no control over the accuracy, accessibility, copyright or trademark compliance, or legality of the material contained on this site.</p></div></aside><p style=\"box-sizing: inherit; margin-top: 1em; margin-bottom: 0px; line-height: 1.5; max-width: 68ex;\">Thank you for visiting our site.</p></main><footer id=\"ic3Footer\" class=\"usa-footer usa-footer--slim\" style=\"box-sizing: inherit; font-family: &quot;Source Sans Pro Web&quot;, &quot;Helvetica Neue&quot;, Helvetica, Roboto, Arial, sans-serif; font-size: 1.06rem; line-height: 1.5; overflow: hidden; color: rgb(27, 27, 27);\"><div class=\"grid-container usa-footer__return-to-top\" style=\"box-sizing: inherit; padding: 1.25rem 2rem; line-height: 0.9; margin-left: auto; margin-right: auto; max-width: 64rem;\"><a href=\"https://www.ic3.gov/Egress/https/www.aba.com/443/about-us%E2%81%84press-room%E2%81%84press-releases%E2%81%84ABA-Foundation-and-FBI-Joint-Infographic-on-Deepfake-Scams/69DA2C756D1C4BD68A50B435DBE503B24A1D71E74CDF4D387045ACE9D94B6A14#\" style=\"box-sizing: inherit; color: rgb(0, 94, 162); text-decoration-line: underline;\">Return to top</a></div></footer>', 2025, '2025-09-04', '', '', 1756915200, 1766501144),
(5, 'PSA251219', 'Senior U.S. Officials Continue to be Impersonated in Malicious Messaging Campaign', '<aside style=\"border: unset; padding: unset; background-color: unset; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>This is an update to Public Service Announcement I-051525-PSA, released&nbsp;<time datetime=\"2025-05-15\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: center;\">May 15, 2025</time>, which can be found&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2025/PSA250515\">here</a>.</p></aside><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">Activity dating back to 2023 reveals malicious actors have impersonated senior U.S. state government, White House, and Cabinet level officials, as well as members of Congress to target individuals, including officials\' family members and personal acquaintances. If you receive a message claiming to be from a current or former senior U.S. official, do not assume it is authentic and follow the below recommendations to identify suspicious messages.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">How It Works</h2><picture><source srcset=\"/img/PSA/2025/251219.webp\" type=\"image/webp\"><img class=\"float-right\" src=\"https://www.ic3.gov/img/PSA/2025/251219.jpg\" alt=\"Diagram showing the activity flow of the impersonation campaign. An actor impersonates a high-ranking official, and uses an encrypted application to do one or more of the following: discuss current events, request a wire transfer, propose a meeting with high-ranking officials, note an appointment to company leadership, request copies of personal documents, or ask about U.S. policy.\" style=\"max-width: 100%; height: auto; display: block; margin: 0px auto;\"></picture><p>Since at least 2023, malicious actors have sent text messages and&nbsp;<abbr title=\"artificial intelligence\" style=\"text-decoration: unset;\">AI</abbr>-generated voice messages — techniques known as smishing and vishing, respectively — that claim to come from a senior U.S. official to establish rapport with targeted individuals. In the scheme, actors contact and individual and briefly engage on a topic the victim is versed on, with a request to move communication to a secondary, encrypted mobile messaging application happening almost immediately. Once communication is established on an encrypted messaging application, actors continue to engage the victim in any number of ways, including but not limited to:</p><ul><li>Discussion on a topic the victim is well-versed in, current events, or bilateral relations, including asking about trade and security policy negotiations;</li><li style=\"margin-top: 0.5rem;\">Propose scheduling a meeting between the victim and the president of the United States or other high-ranking officials; or</li><li style=\"margin-top: 0.5rem;\">Note the victim is being considered for a nomination to a company\'s board of directors.</li></ul><p>Actors have also requested victims take certain actions, such as:</p><ul><li>Provide an authentication code that allows the actors to sync their device with the victim\'s contact list<sup id=\"ref1\"><a aria-label=\"footnote\" href=\"https://www.ic3.gov/PSA/2025/PSA251219#fn1\">1</a></sup>;</li><li style=\"margin-top: 0.5rem;\">Supply Personally Identifiable Information (<abbr>PII</abbr>) and copies of sensitive personal documents, such as a passport;</li><li style=\"margin-top: 0.5rem;\">Wire funds to an overseas financial institution under false pretenses; and</li><li style=\"margin-top: 0.5rem;\">Request the victim introduce the actor to a known associate.</li></ul><p>In most cases, actors make initial contact with a victim via&nbsp;<abbr title=\"short message service\" style=\"text-decoration: unset;\">SMS</abbr>&nbsp;and request the conversation be moved to encrypted mobile applications, such as Signal, Telegram, and WhatsApp. An example of an initial message is below.</p><picture><source srcset=\"/img/PSA/2025/251219-2.webp\" type=\"image/webp\"><img src=\"https://www.ic3.gov/img/PSA/2025/251219-2.jpg\" alt=\"Simple diagram of a smartphone with a generic text-messaging app interface. The message reads: [redacted content] let\'s schedule a Signal call. My Signal no is [redacted content] You have a message from the [redacted content]\'\" style=\"max-width: 100%; height: auto; display: block; margin: 0.5em auto;\"></picture><article class=\"definitions\" style=\"border-top: 4px solid rgb(0, 101, 173); border-bottom: 4px solid rgb(0, 101, 173); color: rgb(0, 101, 173); font-style: italic; padding: 0.5rem 0.25rem;\"><dfn>Smishing</dfn>&nbsp;is the malicious targeting of individuals using Short Message Service (SMS) or Multimedia Message Service (<abbr>MMS</abbr>) text messaging.&nbsp;<dfn>Vishing</dfn>&nbsp;which may incorporate AI-generated voices, is the malicious targeting of individuals using voice memos. Both smishing and vishing use tactics like&nbsp;<dfn>spear phishing</dfn>, which uses email to target specific individuals or groups.</article></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Recommendations</h2><p>The following guidance can be used to identify a suspicious message and help protect yourself from this campaign.</p><section><h3 style=\"font-size: medium;\">Spotting a Fake Message</h3><ul><li>Verify the identity of the person calling you or sending text or voice messages. Before responding, research the originating number, organization, and/or person purporting to contact you. Then independently identify a phone number for the person and call to verify their authenticity.</li><li style=\"margin-top: 0.5rem;\">Carefully examine the email address, messaging contact information, including phone numbers,&nbsp;<abbr title=\"uniform resource locators\" style=\"text-decoration: unset;\">URLs</abbr>, and spelling used in any correspondence or communications. Scammers often use slight differences to deceive you and gain your trust. For instance, actors can incorporate publicly available photographs in text messages, use minor alterations in names and contact information, or use AI-generated voices to masquerade as a known contact.</li><li style=\"margin-top: 0.5rem;\">Look for subtle imperfections in images and videos, such as distorted hands or feet, unrealistic facial features, indistinct or irregular faces, unrealistic accessories such as glasses or jewelry, inaccurate shadows, watermarks, voice call lag time, voice matching, and unnatural movements.</li><li style=\"margin-top: 0.5rem;\">Listen closely to the tone and word choice to distinguish between a legitimate phone call or voice message from a known contact versus AI-generated voice cloning, as they can sound nearly identical.</li><li style=\"margin-top: 0.5rem;\">AI-generated content has advanced to the point that it is often difficult to identify. When in doubt about the authenticity of someone wishing to communicate with you, contact your relevant security officials or the&nbsp;<abbr title=\"Federal Bureau of Investigation\" style=\"text-decoration: unset;\">FBI</abbr>&nbsp;for help.</li></ul></section><section><h3 style=\"font-size: medium;\">How to protect Yourself from Potential Fraud or Loss of Sensitive Information</h3><ul><li>Never share sensitive information or an associate\'s contact information with people you have only met online or over the phone. If contacted by someone you know well via a new platform or phone number, verify the new contact information through a previously confirmed platform or trusted source.</li><li style=\"margin-top: 0.5rem;\">Do not send money, gift cards, cryptocurrency, or other assets to people you do not know of have only met online or over the phone. If someone you know (or an associated of someone you know) requests that you send money or cryptocurrency, independently confirm their contact information prior to taking action. Also, critically evaluate the context and plausibility of the request.</li><li style=\"margin-top: 0.5rem;\">Do not click on any links in an email or text message until you independently confirm the sender\'s identity.</li><li style=\"margin-top: 0.5rem;\">Be careful what you download. Never open an email attachment, click on links in messages, or download applications at the request of or from someone you have not verified.</li><li style=\"margin-top: 0.5rem;\">Set up two-factor (or multi-factor) authentication on any account that allows it and never disable it. Actors may use social engineering techniques to convince you to disclose a two-factor authentication code, which allows the actor to compromise and take over accounts. Never provide a two-factor code to anyone over email, SMS/MMS text message, or encrypted messaging application.</li><li style=\"margin-top: 0.5rem;\">Create a secret word or phrase with your family members to verify their identities.</li></ul></section><section><h3 style=\"font-size: medium;\">Victim Reporting and Additional Information</h3><ul><li>For additional information, see FBI\'s guidance on&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/how-we-can-help-you/scams-and-safety/common-frauds-and-scams/spoofing-and-phishing\">Spoofing and Phishing</a>&nbsp;as well as a previous Public Service Annoucement about how \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA241203\">Criminals Use Generative Artificial Intelligence to Facilitate Financial Fraud</a>\". Cybersecurity and Infrastructure Security Agency (<abbr>CISA</abbr>) has published the following resources \"<a target=\"_blank\" href=\"https://www.cisa.gov/resources-tools/resources/phishing-guidance-stopping-attack-cycle-phase-one\">Phishing Guidance: Stopping the Attack Cycle at Phase One | CISA</a>\" and \"<a target=\"_blank\" href=\"https://www.cisa.gov/audiences/small-and-medium-businesses/secure-your-business/teach-employees-avoid-phishing\">Teach Employees to Avoid Phishing | CISA</a>\".</li></ul></section><p>If you believe you have been the victim of the campaign described above, contact your relevant security officials. The FBI requests victims report any incident to the Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">https://www.ic3.gov/</a>.</p></section><blockquote style=\"border-width: thin; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-color: currentcolor; border-image: initial; padding: 0.5em; background-color: rgb(238, 238, 238); color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Disclaimer</h2><p>The information in this document is being provided \"as is\" for informational purposes only. The FBI does not endorse any commercial entity, product, company, or service, including any entities, products, or services linked within this document. Any reference to specific commercial entities, products, processes, or services by service mark, trademark, manufacturer, or otherwise, does not constitute or imply endorsement, recommendation, or favoring by FBI.</p></blockquote><footer class=\"footnote\" style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><hr><p id=\"fn1\"><sup>1</sup>Access to the targeted individual\'s contact list is used to enable further impersonation efforts or targeting. Once actors have access to the victim\'s contact list, they send out another round of smishing or vishing messages, this time impersonating the last victim or another notable figure the new targeted individual would logically come in contact with.<a title=\"Jump back to footnote 1 in the text\" href=\"https://www.ic3.gov/PSA/2025/PSA251219#ref1\">↩</a></p></footer>', 2025, '2025-12-19', '', '', 1766073600, 1766501715),
(6, 'PSA251217', 'Great Odds, High Risk: The FBI Encourages U.S. Bettors to Know the Risks of Illegal Gambling', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">While sports betting has become more widespread in the U.S., with 39 states and the District of Columbia legalizing some form of sports betting, illegal sportsbooks and illegal online gaming sites are still prevalent. These illegal sportsbooks and online gaming sites have significant consequences for the American public, the U.S. economy, and the integrity of sports betting in the U.S. Individuals engaged in illegal gambling risk funding organized crime activity and becoming vulnerable to violence, extortion, and fraud. As a federal law enforcement agency, the FBI enforces criminal statutes, including those involving organized crime and illegal gambling operations. The FBI emphasizes each bettor\'s individual responsibility to ensure they wager legally and responsibly.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">As of August 2025, the American Gaming Association estimated Americans wager $673.6 billion annually in illegal and unregulated markets – which includes sports betting, online games, and unregulated machines.<sup id=\"ref1\"><a aria-label=\"footnote\" href=\"https://www.ic3.gov/PSA/2025/PSA251217#fn1\">1</a></sup>&nbsp;While some online gaming websites are legal elsewhere in the world, they are still operating illegally in the United States dependent on state regulations. Many offshore gambling websites advertise towards U.S. consumers, obfuscating their overseas presence, and providing U.S. consumers with a false sense of comfort. These offshore sportsbooks are not held to the same legal standards as U.S. licensed sportsbooks and may lack consumer protections, increasing the risks for U.S.-based users.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FBI Crime and Corruption in Sport and Gaming Program combats threats of influence from organized crime groups and other criminals who seek to operate illegal gambling operations and undermine the integrity of sport. Organized crime groups run illegal gambling operations, including online sportsbooks, to generate revenue for other criminal activities, such as human, drug, and weapons trafficking. One of the FBI\'s priorities is to investigate organized crime groups who operate illegal sportsbooks to disrupt and dismantle these operations. Beyond the possible funding of organized crime activity, bettors who wager with illegal bookmakers put themselves at risk of extortion and violence if they are unable to repay debts. Furthermore, unregulated sportsbooks and offshore gambling websites put U.S. consumers at risk of losing their money and earnings. Illegal betting can also lead bettors to other criminal activity, such as tax evasion and money laundering, due to the illicit nature of the financial gains. It is each bettor\'s responsibility to play with a licensed and regulated sportsbook operator.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself by Betting Legally and Responsibly</h2><ul><li>Stay informed of applicable federal, state, and local laws — such as checking your state gaming agency\'s website — to ensure you are betting through a legal sportsbook operator.</li><li style=\"margin-top: 0.5rem;\">The FBI encourages individuals with information on illegal sportsbook operations or other relevant criminal activity to file a report through the Internet Crime Complaint Center (<abbr>IC3</abbr>),&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</li><li style=\"margin-top: 0.5rem;\">Visit&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/\">www.fbi.gov</a>&nbsp;to learn more about the&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/investigate/transnational-organized-crime/integrity-in-sports-and-gaming\">FBI\'s Crime and Corruption in Sport and Gaming Program</a>.</li><li style=\"margin-top: 0.5rem;\">Discover educational resources and tools to support responsible play at the American Gaming Association\'s&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/playsmartfromthestart.org/443/A3B0C8719667C1B9AFCF1450A218CF70568868E8CF1298C69264845ABB719DC0\">Play Smart from the Start consumer hub</a>.</li></ul></section><footer class=\"footnote\" style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><hr><p id=\"fn1\"><sup>1</sup><cite>American Gaming Association (2025 August 13). Sizing the Illegal and Unregulated Gaming Markets.</cite>&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/www.americangaming.org/443/resources%E2%81%84sizing-the-illegal-and-unregulated-gaming-markets%E2%81%84/94600B410237A2AE6C0825CED9134E76F01594EB6A3027DE8B6042291D6F9833\">https://www.americangaming.org/resources/sizing-the-illegal-and-unregulated-gaming-markets/</a>.<a title=\"Jump back to footnote 1 in the text\" href=\"https://www.ic3.gov/PSA/2025/PSA251217#ref1\">↩</a></p></footer>', 2025, '2025-12-17', '', '', 1765900800, 1766501928),
(7, 'PSA251205', 'Criminals Using Altered Proof-of-Life Media to Extort Victims in Virtual Kidnapping for Ransom Scams', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) warns the public about criminals altering photos found on social media or other publicly available sites to use as fake proof of life photos in virtual kidnapping for ransom scams. The criminal actors pose as kidnappers and provide seemingly real photos or videos of victims along with demands for ransom payments.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">The Scam</h2><p>Criminal actors typically will contact their victims through text message claiming they have kidnapped their loved one and demand a ransom be paid for their release. Oftentimes, the criminal actor will express significant claims of violence towards the loved one if the ransom is not paid immediately. The criminal actor will then send what appears to be a genuine photo or video of the victim’s loved one, which upon close inspection often reveals inaccuracies when compared to confirmed photos of the loved one. Examples of these inaccuracies include missing tattoos or scars and inaccurate body proportions. Criminal actors will sometimes purposefully send these photos using timed message features to limit the amount of time victims have to analyze the images.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li>When posting missing person information online, be mindful that scammers may contact you with fake information regarding your loved one.</li><li style=\"margin-top: 0.5rem;\">Avoid providing personal information to strangers while traveling.</li><li style=\"margin-top: 0.5rem;\">Establish a code word only you or your loved ones know that you can use to communicate.</li><li style=\"margin-top: 0.5rem;\">Scammers portray a false sense of urgency. Stop and think; do the kidnapper’s claims make sense?</li><li style=\"margin-top: 0.5rem;\">Screenshot or record proof of life photos whenever possible.</li><li style=\"margin-top: 0.5rem;\">Always attempt to contact your loved one before considering paying any ransom demand.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>If you believe you have been a victim of a virtual kidnapping scam, please report the incident to the FBI\'s Internet Crime Complaint Center at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to submit as much information as possible about the interaction including phone numbers, payment information, text and audio communications, and proof of life photos.</p></section>', 2025, '2025-12-05', '', '', 1764864000, 1766502504),
(8, 'PSA251125', 'Account Takeover Fraud via Impersonation of Financial Institution Support', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FBI warns of cyber criminals impersonating financial institutions to steal money or information in Account Takeover (<abbr>ATO</abbr>) fraud schemes. The cyber criminals target individuals, businesses, and organizations of varied sizes and across sectors. In ATO fraud, cyber criminals gain unauthorized access to the targeted online financial institution, payroll, or health savings account, with the goal of stealing money or information for personal gain. Since January 2025, the FBI Internet Crime Complaint Center (<abbr>IC3</abbr>) received more than 5,100 complaints reporting ATO fraud, with losses exceeding $262 million.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">How It Works</h2><p>The cyber criminal impersonates the financial institution\'s staff or website, to obtain access to the account. Cyber criminals usually gain access to accounts through social engineering techniques — including texts, calls, and emails — or through fraudulent websites.</p><section><h3 style=\"font-size: medium;\">Social Engineering</h3><ul><li>A cyber criminal manipulates the account owner into giving away their login credentials, including multi-factor authentication (<abbr>MFA</abbr>) code or One-Time Passcode (<abbr>OTP</abbr>), by impersonating a financial institution employee, customer support, or technical support personnel. The cyber criminal then uses login credentials to log into the legitimate financial institution website and initiate a password reset, ultimately gaining full control of the accounts.</li><li style=\"margin-top: 1rem;\">Social engineering methods include contacting account owners via fraudulent text messages, calls, or emails to trick the email recipient into providing their login credentials. In some instances, the cyber criminal states there are fraudulent transactions on the financial account and may provide a link to a phishing website that the account owner believes will report the fraud or prevent additional fraudulent transactions.</li><li style=\"margin-top: 1rem;\">In some instances, cyber criminals impersonating financial institutions reported to the account owner that their information was used to make fraudulent purchases, including firearms. The cyber criminal convinces the account owner to provide information to a second cyber criminal impersonating law enforcement, who then convinces the account owner to provide account information.</li></ul></section><section><h3 style=\"font-size: medium;\">Phishing Domains/Websites</h3><ul><li>The cyber criminal uses a phishing website that looks like the legitimate online financial institution or payroll website to trick the account owner into giving away their login credentials. Believing the phishing website is the legitimate one, users enter their login credentials into the fraudulent site, unknowingly providing them to cyber criminals.</li><li style=\"margin-top: 1rem;\">Cyber criminals may also use a technique called Search Engine Optimization (<abbr>SEO</abbr>) poisoning.&nbsp;<dfn style=\"font-style: unset;\">SEO poisoning</dfn>&nbsp;refers to cyber criminals purchasing ads that imitate legitimate business ads to increase the prominence of their phishing websites by making them appear more authentic to customers who use a search engine to locate the business\' website. When users click on the fraudulent search engine ad, they are directed to a sophisticated fraudulent phishing site that mimics the real website, tricking users into providing their login information.</li></ul></section><p>Once the impersonators have access and control of the accounts, the cyber criminals quickly wire funds to other criminal-controlled accounts, many of which are linked to cryptocurrency wallets; therefore, funds are disbursed quickly and are difficult to trace and recover. In some cases, including nearly all social engineering cases, the cyber criminals change the online account password, locking the owner out of their own financial account(s).</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Stay Protected</h2><p>Stay vigilant against ATO fraud attempts by following these tips.</p><ul class=\"tips\" style=\"display: flex; flex-wrap: wrap; list-style-type: none; padding-left: unset; gap: 0.5rem; justify-content: center;\"><li style=\"min-width: 10rem; max-width: 30%; background-color: rgb(0, 0, 255); color: rgb(255, 255, 255); box-shadow: rgb(51, 51, 51) 2px 2px 3px; text-align: center; padding: 0.5rem 0.3rem; display: flex; flex-direction: column;\"><h3 style=\"font-size: unset; font-weight: bold; font-style: italic;\">Be careful about the information you share online or on social media.</h3><p style=\"flex-grow: 1; display: flex; align-items: center;\">By openly sharing information like a pet\'s name, schools you have attended, your date of birth, or information about your family members, you may give scammers the information they need to guess your password or answer your security questions.</p></li><li style=\"margin-top: unset; min-width: 10rem; max-width: 30%; background-color: rgb(0, 0, 255); color: rgb(255, 255, 255); box-shadow: rgb(51, 51, 51) 2px 2px 3px; text-align: center; padding: 0.5rem 0.3rem; display: flex; flex-direction: column;\"><h3 style=\"font-size: unset; font-weight: bold; font-style: italic;\">Monitor your financial accounts on a regular basis.</h3><p style=\"flex-grow: 1; display: flex; align-items: center;\">Watch for irregularities, such as missing deposits or unauthorized withdrawals, wire transfers, or expenditures.</p></li><li style=\"margin-top: unset; min-width: 10rem; max-width: 30%; background-color: rgb(0, 0, 255); color: rgb(255, 255, 255); box-shadow: rgb(51, 51, 51) 2px 2px 3px; text-align: center; padding: 0.5rem 0.3rem; display: flex; flex-direction: column;\"><h3 style=\"font-size: unset; font-weight: bold; font-style: italic;\">Always use unique, complex passwords.</h3><p style=\"flex-grow: 1; display: flex; align-items: center;\"></p><div>Enable two-factor authentication or MFA on any account possible.&nbsp;<span style=\"font-style: unset; text-decoration-line: underline;\">Never</span>&nbsp;disable it.</div><p style=\"flex-grow: 1; display: flex; align-items: center;\"></p></li><li style=\"margin-top: unset; min-width: 10rem; max-width: 30%; background-color: rgb(0, 0, 255); color: rgb(255, 255, 255); box-shadow: rgb(51, 51, 51) 2px 2px 3px; text-align: center; padding: 0.5rem 0.3rem; display: flex; flex-direction: column;\"><h3 style=\"font-size: unset; font-weight: bold; font-style: italic;\">Use Bookmarks or Favorites for navigating to login websites.</h3><p style=\"flex-grow: 1; display: flex; align-items: center;\">Avoid clicking on Internet search results or advertisements. MFA will not protect you if you land on a fraudulent login page. Carefully examine any email address, URL, or spelling in unsolicited correspondence.</p></li><li style=\"margin-top: unset; min-width: 10rem; max-width: 30%; background-color: rgb(0, 0, 255); color: rgb(255, 255, 255); box-shadow: rgb(51, 51, 51) 2px 2px 3px; text-align: center; padding: 0.5rem 0.3rem; display: flex; flex-direction: column;\"><h3 style=\"font-size: unset; font-weight: bold; font-style: italic;\">Stay vigilant against phishing attempts.</h3><p style=\"flex-grow: 1; display: flex; align-items: center;\">Be suspicious of unknown \"banking\" or \"company\" employees who call you; don\'t trust caller ID. Hang up, verify the correct number, and call it yourself. Companies generally do not contact you to ask for your username, password, or OTP.</p></li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">What To Do in Case of an ATO Incident</h2><ol class=\"orb\" style=\"margin-left: 0px; padding-right: 0px; list-style: none;\"><li style=\"counter-increment: num 1;\"><h3 style=\"font-size: medium; float: left;\">Contact Your Financial Institution</h3><p style=\"clear: left; margin-left: -1.5rem;\">Contact your financial institution as soon as fraud is recognized to request a recall or reversal as well as a Hold Harmless Letter or Letter of Indemnity. Requesting a recall and obtaining a Hold Harmless Letter/indemnification documents as quickly as possible may reduce or eliminate your financial losses. Immediately report fraudulent wire transfers to both to your financial institution and to the FBI Internet Crime Complaint Center (IC3) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</p></li><li style=\"margin-top: 1rem; counter-increment: num 1;\"><h3 style=\"font-size: medium; float: left;\">Reset or Revoke Compromised Credentials</h3><p style=\"clear: left; margin-left: -1.5rem;\">Reset all credentials and passwords that may have been exposed during the intrusion, including user and service accounts, compromised certificates, or other \"secret\" credentials. If you use the compromised password for other online accounts, change your password on those sites too.</p></li><li style=\"margin-top: 1rem; counter-increment: num 1;\"><h3 style=\"font-size: medium; float: left;\">File a Complaint</h3><p style=\"clear: left; margin-left: -1.5rem;\">File a detailed complaint with www.ic3.gov. It is vital the complaint contain all required data in provided fields, including banking information.</p><ul style=\"list-style-type: disc; padding-left: 1rem;\"><li>Identifying information about the cyber criminals including the financial institution impersonated, name, phone number, address, and email address.</li><li style=\"margin-top: 1rem;\">Any websites or software the cyber criminals may have asked you to visit or download.</li><li style=\"margin-top: 1rem;\">Any financial accounts provided or used by the cyber criminals.</li><li style=\"margin-top: 1rem;\">Include the words \"Account Takeover\" or \"SEO poisoning\" in the incident description.</li></ul></li><li style=\"margin-top: 1rem; counter-increment: num 1;\"><h3 style=\"font-size: medium; float: left;\">Notify the Impersonated Company</h3><p style=\"clear: left; margin-left: -1.5rem;\">Notify the company that was impersonated of the method the cyber criminals used to target the account owner. The company may be able to warn others to watch out for the scam and take proactive measures like requesting phishing pages be taken down.</p></li><li style=\"margin-top: 1rem; counter-increment: num 1;\"><h3 style=\"font-size: medium; float: left;\">Stay Informed</h3><p style=\"clear: left; margin-left: -1.5rem;\">Visit&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>&nbsp;for updated Industry Alerts and Public Service Announcements regarding ATO trends, as well as other cyber-enabled fraud schemes.</p></li></ol></section>', 2025, '2025-11-25', '', '', 1764000000, 1766502669),
(16, 'PSA250820', 'Russian Government Cyber Actors Targeting Networking Devices, Critical Infrastructure', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is warning the public, private sector, and international community of the threat posed to computer networks and critical infrastructure by cyber actors attributed to the Russian Federal Security Service\'s (<abbr>FSB</abbr>) Center 16. The FBI detected Russian FSB cyber actors exploiting Simple Network Management Protocol (<abbr>SNMP</abbr>) and end-of-life networking devices running an unpatched vulnerability (CVE-2018-0171) in Cisco Smart Install (<abbr>SMI</abbr>) to broadly target entities in the United States and globally.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">In the past year, the FBI detected the actors collecting configuration files for thousands of networking devices associated with US entities across critical infrastructure sectors. On some vulnerable devices, the actors modified configuration files to enable unauthorized access to those devices. The actors used the unauthorized access to conduct reconnaissance in the victim networks, which revealed their interest in protocols and applications commonly associated with industrial control systems.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FSB Center 16 unit conducting this activity is known to cybersecurity professionals by several names, including \"Berserk Bear\" and \"Dragonfly,\" which refer to separate but related cyber activity clusters. For over a decade, this unit has compromised networking devices globally, particularly devices accepting legacy unencrypted protocols like SMI and SNMP versions 1 and 2. This unit has also deployed custom tools to certain Cisco devices, such as the malware publicly identified as \"SYNful Knock\" in 2015.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FBI and law enforcement partners previously released guidance that remains relevant in a Technical Alert, \"<a target=\"_blank\" href=\"https://www.cisa.gov/news-events/alerts/2018/04/16/russian-state-sponsored-cyber-actors-targeting-network-infrastructure\">Russian State-Sponsored Cyber Actors Targeting Network Infrastructure Devices</a>\" on 20 April 2018, and a Joint Advisory, \"<a target=\"_blank\" href=\"https://www.cisa.gov/resources-tools/resources/primary-mitigations-reduce-cyber-threats-operational-technology\">Primary Mitigations to Reduce Cyber Threats to Operational Technology</a>\" on 6 May 2025. In addition, Cisco Talos published a blog post on 20 August 2025 with more information on their analysis of this threat actor, identified by Cisco Talos as Static Tundra.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">If you suspect you have been targeted or compromised by a Russian FSB cyber intrusion, immediately report the activity to your&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">local FBI field office</a>&nbsp;or file a report on the&nbsp;<a target=\"_blank\" href=\"http://www.ic3.gov/\">FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>)</a>.</p><p class=\"press-release__headline\" style=\"margin-bottom: 0px; font-weight: 700; color: rgb(80, 80, 80); font-family: Lato, sans-serif; font-size: 18px;\">About the American Bankers Association</p><p style=\"margin-bottom: 15px; color: rgb(80, 80, 80); font-family: Lato, sans-serif; font-size: 18px;\">The American Bankers Association is the voice of the nation’s $25.1 trillion banking industry, which is composed of small, regional and large banks that together employ over 2 million people, safeguard $19.7 trillion in deposits and extend $13.2 trillion in loans.</p><p class=\"press-release__headline\" style=\"margin-bottom: 0px; font-weight: 700; color: rgb(80, 80, 80); font-family: Lato, sans-serif; font-size: 18px;\">About the ABA Foundation</p><p style=\"margin-bottom: 15px; color: rgb(80, 80, 80); font-family: Lato, sans-serif; font-size: 18px;\">Through its leadership, partnerships, and national programs, ABA’s Community Engagement Foundation (dba ABA Foundation), a 501(c)3, helps bankers provide financial education to individuals at every age, elevate issues around affordable housing and community development, and achieve corporate social responsibility objectives to improve the well-being of their customers and their communities.</p>', 2025, '2025-08-20', '', '', 1755619200, 1766504596);
INSERT INTO `ic3_psa` (`id`, `code`, `title`, `content`, `publish_year`, `publish_date`, `file_zh`, `file_tw`, `createtime`, `updatetime`) VALUES
(17, 'PSA250813', 'Fictitious Law Firms Targeting Cryptocurrency Scam Victims Combine Multiple Exploitation Tactics While Offering to Recover Funds', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">This PSA is an update to Alert Number I-062424-PSA titled, \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA240624\">Fictitious Law Firms Targeting Cryptocurrency Scam Victims Offering to Recover Funds.</a>\" This updated advisory provides additional red flag indicators and due diligence measures to help victims who have been in contact with fictitious law firms conducting this fraudulent activity.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">This scheme combines a number of exploitation tactics including targeting vulnerable populations, particularly the elderly; exploiting victims\' emotional state and financial need to recover funds from a previous scam; and giving victims the sense of safety and security by impersonating or falsely affiliating themselves with multiple government entities. Contact with scammers impersonating law firms continue to pose many risks, including the theft of personal data and funds from unsuspecting victims to the reputational harm of actual lawyers being impersonated.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h3 style=\"font-size: medium;\">Red Flag Indicators of Potential Fictitious Law Firm Activity:</h3><ul><li>Impersonation of actual lawyers and/or legitimate law firms and the production of fictitious documents with a legitimate law firm insignia or letterhead.</li><li style=\"margin-top: 0.5rem;\">Impersonation or affiliation as official authorized partners with multiple US and foreign government or regulatory entities. There are no law firms which are officially authorized partners of US Government agencies.</li><li style=\"margin-top: 0.5rem;\">References to fictitious government or regulatory entities, such as the International Financial Trading Commission (<abbr>INTFTC</abbr>). Double check whether such an agency exists.</li><li style=\"margin-top: 0.5rem;\">Requesting payment in cryptocurrency or prepaid gift cards. The US Government does not request payment for law enforcement services provided.</li><li style=\"margin-top: 0.5rem;\">Having knowledge of the exact amounts and dates of previous wire transfers and the third-party company where the victim previously sent scammed funds.</li><li style=\"margin-top: 0.5rem;\">Stating the victim was on a government-affiliated list of scam victims and they can recover their money through \"legal channels.\"</li><li style=\"margin-top: 0.5rem;\">Referring victims to a \"crypto recovery law firm.\"</li><li style=\"margin-top: 0.5rem;\">State the victims\' funds are in an account held at a foreign bank and tell victims to register an account at that bank. The domain or website provided for this bank appears legitimate but is a fraudulent platform to facilitate the ongoing scheme.</li><li style=\"margin-top: 0.5rem;\">Placing victims into a group chat on WhatsApp, or other messaging applications, for supposed secrecy and safety of the client with supposed foreign bank processors and attorneys who may say that payment of bank fees is required to verify identity and ownership to withdraw funds.</li><li style=\"margin-top: 0.5rem;\">An unwillingness or inability to provide credentials or a license, not appearing on camera, and not conducting video meetings.</li><li style=\"margin-top: 0.5rem;\">Request victims send payment to a third-party entity (i.e., xyz trading company) for the supposed purposes of maintaining secrecy and safety.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h3 style=\"font-size: medium;\">Additional Due Diligence Measures to Prevent Hiring of Fictitious Law Firms:</h3><ul><li>Use a \"Zero Trust\" model in these circumstances, which assumes no one should be trusted by default and every request should be verified.</li><li style=\"margin-top: 0.5rem;\">Be cautious of law firms contacting you unexpectedly, especially if you have not reported the crime to any law enforcement or civil protection agencies.</li><li style=\"margin-top: 0.5rem;\">Request video verification or documentation or a photo of their law license. If this cannot be readily provided, assume they are not legitimate.</li><li style=\"margin-top: 0.5rem;\">Request verification of employment for anyone claiming to work for the US Government or law enforcement. You can call your local office for the associated government entity and request to verify the identity of the individual with whom you are communicating.</li><li style=\"margin-top: 0.5rem;\">Keep records, including recordings of video chats of all interactions.</li><li style=\"margin-top: 0.5rem;\">Require notarized proofs of identity from the supposed lawyers before continuing any further communications and transactions.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Victim Reporting</h2><p>The FBI requests victims of fraudulent law firm scams, or those who suspect they may have been victimized, to report the suspicious activity to their local FBI field office and the FBI\'s Internet Crime Compliant Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Additional Resources</h2><ul class=\"psa-resources\" style=\"padding-left: 0px; list-style-type: none;\"><li>This PSA is an update to Alert Number I-062424-PSA, published on&nbsp;<time datetime=\"2024-06-24T10:00:00.000-04:00\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: unset;\">24 June 2024</time>, titled \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA240624\">Fictitious Law Firms Targeting Cryptocurrency Scam Victims Offering to Recover Funds</a>.\"</li><li style=\"margin-top: 1rem;\">This PSA is an update to Alert Number I-081123-PSA, published on&nbsp;<time datetime=\"2023-08-11T12:35:00.000-04:00\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: unset;\">11 August 2023</time>, titled, \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2023/PSA230811\">Increase in Companies Falsely Claiming an Ability to Recover Funds Lost in Cryptocurrency Investment Scams</a>.\"</li></ul></section>', 2025, '2025-08-13', '', '', 1755014400, 1766504755),
(18, 'PSA250731', 'Unsolicited Packages Containing QR Codes Used to Initiate Fraud Schemes', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The FBI warns the public about a scam variation in which criminals send unsolicited packages containing a QR code<sup id=\"retfn1\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250731#fn1\" aria-label=\"footnote\">1</a></sup>&nbsp;that prompts the recipient to provide personal and financial information or unwittingly download malicious software that steals data from their phone. To encourage the victim to scan the QR code, the criminals often ship the packages without sender information to entice the victim to scan the QR code. While this scam is not as widespread as other fraud schemes, the public should be aware of this criminal activity.</p><p>This is a variation of a \"brushing scam,\" which is used by online vendors to increase ratings of their products. In a traditional brushing scam, online vendors send merchandise to an unsolicited recipient and then use the recipient\'s information to post a positive review of the product. In this variation, scam actors have incorporated the use of QR codes on packages to facilitate financial fraud activities.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><p>Criminals continue to evolve their tactics to target unsuspecting victims. Precautions should be taken prior to scanning any QR codes received through unsolicited communications or packages.</p><ul><li>Beware of unsolicited packages containing merchandise you did not order.</li><li style=\"margin-top: 0.5rem;\">Beware of packages that do not include sender information.</li><li style=\"margin-top: 0.5rem;\">Take precautions before authorizing phone permissions and access to websites and applications.</li><li style=\"margin-top: 0.5rem;\">Do not scan QR codes from unknown origins.</li><li style=\"margin-top: 0.5rem;\">If you believe you are the target of a brushing scam, secure your online presence by changing account profiles and request a free credit report from one or all the national credit reporting agencies (Equifax, Experian, and TransUnion) to identify possible fraudulent activity.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>The FBI requests the public report these fraudulent or suspicious activities to the FBI IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much information as possible:</p><ul><li>The name of the person or company that contacted you.</li><li style=\"margin-top: 0.5rem;\">Methods of communication used, including websites, emails, and telephone numbers.</li><li style=\"margin-top: 0.5rem;\">Any applications you may have downloaded or provided permissions to on your electronic device.</li></ul><p>Individuals aged 60 or over who need assistance with filing an IC3 complaint can contact the DOJ Elder Justice Hotline,&nbsp;<a href=\"tel:+1(833)372-8311\">1-833-FRAUD-11</a>&nbsp;(or 833-372-8311).</p></section><p>For additional information on similar scams, please see previous Public Service Announcements:</p><ul><li>IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2021/PSA211104\">The FBI Warns of Fraudulent Schemes Leveraging Cryptocurrency ATMs and QR Codes to Facilitate Payment</a>\"</li></ul></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup><dfn>Quick Response codes</dfn>&nbsp;or \"<abbr>QR codes</abbr>\" are scannable codes that connect to a website.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250731#retfn1\" title=\"Jump back to footnote 1 in the text\">↩</a></p></footer>', 2025, '2025-07-31', '', '', 1753891200, 1766513691),
(19, 'PSA250723', 'North Korean IT Worker Threats to U.S. Businesses', '<section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) is providing an update to previously shared guidance regarding Democratic People\'s Republic of Korea (<abbr>North Korea</abbr>) Information Technology (<abbr>IT</abbr>) workers to raise public awareness of the threat posed to U.S. businesses. North Korea is evading U.S. and U.N. sanctions by targeting private companies to illicitly generate substantial revenue for the regime. North Korean IT workers use a variety of techniques to disguise their identities, including leveraging U.S.-based individuals, both witting and unwitting, to gain fraudulent employment and access to U.S. company networks to generate this revenue.</p><p>These witting and unwitting U.S.-based individuals provide a U.S.-based location for companies to send devices, enabling North Korea to circumvent controls companies may have in place to prevent the hiring of illicit, overseas workers as well as controls intended to prevent unauthorized access to company networks by North Korean IT workers, including through the unauthorized installation of remote access software. North Korean IT workers\' activities illegally violate U.S. and U.N. sanctions and threaten the security of the targeted companies. Companies that outsource IT work to third-party vendors can face additional vulnerabilities since these companies are removed from the direct hiring process.</p><p>Specifically, U.S.-based facilitators have provided the following services to North Korean IT workers:</p><ul><li>A U.S.-based internet connection enabled through U.S. company laptops received on their behalf by facilitators in the United States.</li><li style=\"margin-top: 0.5rem;\">Setup of U.S.-based infrastructure, including by enabling remote desktop connections to U.S. company laptops through protocols or remote desktop connection software download and installation.</li><li style=\"margin-top: 0.5rem;\">Reshipment of U.S. company laptops to North Korean IT workers overseas.</li><li style=\"margin-top: 0.5rem;\">Setup of financial accounts for North Korean IT workers. Some U.S.-based facilitators receive shares of the proceeds earned through North Korean IT worker employment schemes.</li><li style=\"margin-top: 0.5rem;\">Creation of accounts on popular job search sites for use by North Korean IT workers.</li><li style=\"margin-top: 0.5rem;\">Assistance purchasing and funding web services, such as artificial intelligence models and background check programs for use by North Korean IT workers.</li><li style=\"margin-top: 0.5rem;\">Attendance at virtual interviews and meetings on behalf of North Korean IT workers; and</li><li style=\"margin-top: 0.5rem;\">Creation of U.S.-based front businesses, including businesses purporting to offer short-term technical contract workers.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Your Business</h2><h3 style=\"font-size: medium;\">Scrutinize identity verification documents</h3><p>Check for misspellings and cross-reference photographs and contact information (e.g. phone numbers, addresses, emails, etc.) with social media profiles, portfolio websites, and payment platforms.</p><h3 style=\"font-size: medium;\">Verify prior employment and education</h3><p>Verify prior employment and higher education history directly with businesses and educational institutions.</p><h3 style=\"font-size: medium;\">Require in-person meetings</h3><p>When possible, mandate in-person drug tests or fingerprinting to verify identity and claimed location. If needing to rely on virtual meetings:</p><ul><li>Mandate video and request that their backgrounds be unobscured.</li><li style=\"margin-top: 0.5rem;\">Have the individual point the camera out a window and ask questions about their claimed current location and the location listed on their identification documents.</li><li style=\"margin-top: 0.5rem;\">Ask the individual to wave their hand in front of their face as it may prompt a malfunction in AI generated video.</li></ul><h3 style=\"font-size: medium;\">Capture images of individuals</h3><p>Capture images for comparison with future meetings. Sometimes an individual is employed to pass the initial interview, but the on-the-job work is completed by a different individual.</p><h3 style=\"font-size: medium;\">Analyze payment methods</h3><p>Compare payment accounts of all employees, flagging those using similar documentation to establish accounts or with matching banking information. Monitor employees who change their bank accounts often, due to banks closing accounts of concern. Beware of agreements to pay employees using virtual currency, which enables funds to be transferred internationally without high levels of scrutiny.</p><h3 style=\"font-size: medium;\">Shipping work related materials</h3><p>If sending documents or work-related equipment such as a laptop, only send to the address listed in the employee\'s identification documents. If the employee requests delivery to a different address, require additional documentation to verify the address. Additionally, do not grant access to any systems until the background check is completed.</p><h3 style=\"font-size: medium;\">Contracted IT workers</h3><p>If your company employs contracted IT workers that have been hired by a third-party company, seek to educate the third-party company about this guidance. Contract IT work is a common way that North Korean IT workers procure employment.</p><h3 style=\"font-size: medium;\">Contact your local FBI Field Office Private Sector Coordinator</h3><p>Building and maintaining a working relationship with your FBI Private Sector Coordinator allows beneficial collaboration and information-sharing between the FBI and the private sector; while mitigating threats through longstanding, mutually beneficial partnerships.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Reporting</h2><p>Report suspected North Korean IT worker activities to:</p><ul><li>Your local FBI Field Office:&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-office\">www.fbi.gov/contact-us/field-office</a></li><li style=\"margin-top: 0.5rem;\">FBI\'s Internet Crime Complaint Center:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a></li><li style=\"margin-top: 0.5rem;\">FBI tip line:&nbsp;<a href=\"tel:+1(800)225-5324\">1-800-CALL-FBI</a>&nbsp;(225-5324)</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Reference</h2><p>In&nbsp;<a target=\"_blank\" href=\"https://ofac.treasury.gov/media/923126/download?inline\">2022</a>&nbsp;and&nbsp;<a target=\"_blank\" href=\"https://2021-2025.state.gov/updated-guidance-on-the-democratic-peoples-republic-of-korea-information-technology-workers\">2023</a>&nbsp;the United States, along with foreign partners, issued public advisories involving North Korean IT workers that described how they operate and provided red flag indicators along with due diligence measures for businesses to avoid hiring North Korean IT workers.</p><p>In&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA240516\">2024</a>&nbsp;and&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2025/PSA250123\">2025</a>&nbsp;FBI provided further guidance regarding North Korean IT workers and their use of witting and unwitting US-based individuals.</p></section>', 2025, '2025-07-23', '', '', 1753200000, 1766532592),
(23, 'PSA250727', 'Fraudsters Target US Stock Investors through Investment Clubs Accessed on Social Media and Messaging Applications', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><main id=\"main\" style=\"margin: 0px 24px;\"><p>The FBI warns the public about criminals targeting US stock investors through social media platforms and messaging service applications (<abbr>apps</abbr>). The scheme, known as a \"<dfn style=\"font-style: normal;\">ramp-and-dump</dfn>\" stock manipulation, targets US investors through online engagement, often via social media advertisements or messages promoting an \"investment club\" of fellow investors, some of which may be bots or fake accounts. These promotions typically direct victims to secure messaging apps where the group operates. To appear credible, perpetrators may impersonate legitimate brokerage firms or well-known stock analysts. They secretly control a large volume of a low-priced stock and coordinate efforts to inflate its price (\"<dfn style=\"font-style: normal;\">ramp up</dfn>\") by encouraging investment club members to purchase shares over a period of several weeks or months. Once the price is artificially elevated, the criminals sell off (\"<dfn style=\"font-style: normal;\">dump</dfn>\") their shares at a profit, leaving unsuspecting investors with significant losses as the stock value collapses.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">Recognize and Avoid \"Ramp-and-dump\" Stock Fraud</h2><p>So far in 2025, the FBI has seen at least a 300 percent increase in victim complaints referencing ramp-and-dump stock fraud from 2024. Investors can protect themselves from potential ramp-and-dump schemes by recognizing the following indicators:</p><ul><li>Unsolicited investment tips received via \"accidental\" text messages or social media advertisements linking to online investment clubs, often hosted on secure messaging apps;</li><li style=\"margin-top: 0.5rem;\">Claims from well-known financial advisors or wealth managers offering exclusive stock recommendations through these online clubs;</li><li style=\"margin-top: 0.5rem;\">Pressure to act quickly based on a supposed market-moving event — such as a company breakthrough, new technology, or government approval; and,</li><li style=\"margin-top: 0.5rem;\">Urgent pitches to purchase low-priced stocks in new or emerging companies, often paired with promises of dramatic price increases or guarantees to cover any investor losses.</li></ul><p>If anyone requests your personal information, access to your financial account(s), or offers a financial benefit in exchange for sharing your information or opening an account, consider this a red flag; your information could be used to open an account through which another party can engage in manipulative activity.</p></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Report Incidents of Investment Fraud</h2><p>The FBI Internet Crime Complaint Center (<abbr>IC3</abbr>) confirms a sharp increase in complaints this past year referencing investment club fraud schemes or ramp-and-dump stock manipulation schemes. The FBI requests investors who suspect they have been victimized by investment fraud to report the incident to the FBI IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>&nbsp;as soon as possible.</p></section></main></main>', 2025, '2025-07-27', '', '', 1753545600, 1766532989),
(25, 'PSA250705', 'Recent Attacks Highlight Elevated Threat to Israeli and Jewish Communities', '<section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Summary</h2><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) and the Department of Homeland Security (<abbr>DHS</abbr>) are issuing this Public Service Announcement to highlight potential public safety concerns related to ongoing threats to Jewish and Israeli communities.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Threat</h2><p>On 1 June 2025, an individual approached several people at a pro-Israel gathering in Boulder, Colorado, and threw two Molotov cocktails at the group, injuring at least nine people. This attack followed a separate attack in late May 2025, in which an individual shot and killed two Israeli Embassy staffers after they attended an event at the Capital Jewish Museum in Washington, DC. The Capital Jewish Museum attacker allegedly cited Israel\'s treatment of the Palestinian people when taken into custody.</p><p>The ongoing Israel-HAMAS conflict may motivate other violent extremists and hate crime perpetrators with similar grievances to conduct violence against Jewish and Israeli communities and their supporters. Foreign terrorist organizations also may try to exploit narratives related to the conflict to inspire attacks in the United States. The FBI and DHS therefore urge the public to remain vigilant and to report any threats of violence or suspicious activity to law enforcement.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Resources</h2><p>The FBI encourages the public to promptly report information concerning suspicious activity to&nbsp;<a target=\"_blank\" href=\"https://tips.fbi.gov/\">tips.fbi.gov</a>&nbsp;or contact their local FBI field office (<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">www.fbi.gov/contact-us/field-offices</a>). Call 911 to report emergencies, including imminent threats to life.</p><p>For concerns involving US citizens abroad, to include reporting missing persons or individuals taken as hostages, please call the Department of State\'s Overseas Citizens Services (<abbr>OCS</abbr>) toll-free hotline at&nbsp;<a href=\"tel:+1(888)407-4747\">(888) 407-4747</a>&nbsp;or complete Crisis Intake Form at&nbsp;<a target=\"_blank\" href=\"https://cacms.state.gov/s/crisis-intake\">https://cacms.state.gov/s/crisis-intake</a>.</p></section>', 2025, '2025-07-05', '', '', 1751644800, 1766533492),
(26, 'PSA250605', 'Home Internet Connected Devices Facilitate Criminal Activity', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) is issuing this Public Service Announcement to warn the public about cyber criminals exploiting Internet of Things (<abbr>IoT</abbr>)<sup id=\"retfn1\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250605#fn1\" aria-label=\"footnote\">1</a></sup>&nbsp;devices connected to home networks to conduct criminal activity using the BADBOX 2.0 botnet<sup id=\"retfn2\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250605#fn2\" aria-label=\"footnote\">2</a></sup>. Cyber criminals gain unauthorized access to home networks through compromised IoT devices, such as TV streaming devices, digital projectors, aftermarket vehicle infotainment systems, digital picture frames and other products. Most of the infected devices were manufactured in China. Cyber criminals gain unauthorized access to home networks by either configuring the product with malicious software prior to the users purchase or infecting the device as it downloads required applications that contain backdoors, usually during the set-up process.<sup id=\"retfn3\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250605#fn3\" aria-label=\"footnote\">3</a></sup>&nbsp;Once these compromised IoT devices are connected to home networks, the infected devices are susceptible to becoming part of the BADBOX 2.0 botnet and residential proxy services<sup id=\"retfn4\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250605#fn4\" aria-label=\"footnote\">4</a></sup>&nbsp;known to be used for malicious activity.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">What is BADBOX 2.0 Botnet</h2><p><dfn style=\"font-style: normal;\">BADBOX 2.0</dfn>&nbsp;was discovered after the original BADBOX campaign was disrupted in 2024. BADBOX was identified in 2023, and primarily consisted of Android operating system devices that were compromised with backdoor malware prior to purchase. BADBOX 2.0, in addition to compromising devices prior to purchase, can also infect devices by requiring the download of malicious apps from unofficial marketplaces. The BADBOX 2.0 botnet consists of millions of infected devices and maintains numerous backdoors to proxy services that cyber criminal actors exploit by either selling or providing free access to compromised home networks to be used for various criminal activity.</p></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Indicators</h2><p>The public is urged to evaluate IoT devices in their home for any indications of compromise and consider disconnecting suspicious devices from their networks. The FBI has identified potential indicators that may assist in detecting malicious devices. An indicator alone does not accurately determine malicious cyber activity or a crime. The following suspicious activities/indicators do not relate to any individual, group, or business and should be observed in context.</p><p>Possible indicators of BADBOX 2.0 botnet activity include:</p><ul><li>The presence of suspicious marketplaces where apps are downloaded.</li><li style=\"margin-top: 0.5rem;\">Requiring Google Play protect settings to be disabled.</li><li style=\"margin-top: 0.5rem;\">Generic TV streaming devices advertised as unlocked or capable of accessing free content.</li><li style=\"margin-top: 0.5rem;\">IoT devices advertised from unrecognizable brands.</li><li style=\"margin-top: 0.5rem;\">Android devices that are not Play Protect certified.</li><li style=\"margin-top: 0.5rem;\">Unexplained or suspicious Internet traffic.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Mitigations</h2><p>The following mitigation strategies can be effective steps to minimize exposure to unauthorized residential proxy networks.</p><ul><li>Maintaining awareness and monitor Internet traffic of home networks.</li><li style=\"margin-top: 0.5rem;\">Assess all IoT devices connected to home networks for suspicious activity.</li><li style=\"margin-top: 0.5rem;\">Avoid downloading apps from unofficial marketplaces advertising free streaming content.</li><li style=\"margin-top: 0.5rem;\">Keeping all operating systems, software, and firmware up to date. Timely patching is one of the most efficient and cost-effective steps to minimize its exposure to cybersecurity threats. Prioritize patching firewall vulnerabilities and known exploited vulnerabilities in internet-facing systems.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Acknowledgements</h2><p>Google, Human Security, Trend Micro, and the Shadowserver Foundation contributed to this product.</p></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Victim Reporting</h2><p>If you believe you have been a victim of an intrusion, please file a report with the FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</p></section><footer class=\"disclaimer\" style=\"border-top: 0.2rem solid rgb(0, 0, 0);\"><h2 style=\"font-size: unset; text-transform: unset;\">Disclaimer</h2><p>The information in this report is being provided \"as is\" for informational purposes only. FBI, does not endorse any commercial entity, product, company, or service, including any entities, products, or services linked within this document. Any reference to specific commercial entities, products, processes, or services by service mark, trademark, manufacturer, or otherwise, does not constitute or imply endorsement, recommendation, or favoring by the FBI.</p></footer></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup><dfn>Internet of Things</dfn>&nbsp;— Refers to a network of devices, vehicles, appliances and other physical objects that are embedded with sensors, software and network connectivity.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250605#retfn1\" title=\"Jump back to footnote 1 in the text\">↩</a></p><p id=\"fn2\"><sup>2</sup><dfn>Botnet</dfn>&nbsp;— A network of Internet-connected devices compromised by malware that can be controlled remotely without the owners\' knowledge.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250605#retfn2\" title=\"Jump back to footnote 2 in the text\">↩</a></p><p id=\"fn3\"><sup>3</sup><dfn>Backdoors</dfn>&nbsp;— A hidden, unauthorized point of entry into a system, which is designed to bypass security measures.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250605#retfn3\" title=\"Jump back to footnote 3 in the text\">↩</a></p><p id=\"fn4\"><sup>4</sup><dfn>Residential Proxy</dfn>&nbsp;— A type of proxy server that uses real IP addresses assigned to residential users by their Internet Service Providers (<abbr>ISPs</abbr>).&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250605#retfn4\" title=\"Jump back to footnote 4 in the text\">↩</a></p></footer>', 2025, '2025-06-05', '', '', 1749052800, 1766535241),
(27, 'PSA250603', 'Cyber Criminals Defraud Hedera Hashgraph Network Non-Custodial Wallet Users Through Nonfungible Token Airdrops Disguised as Free Rewards', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) is issuing this announcement to inform individuals about cyber criminals defrauding cryptocurrency users through the nonfungible token (<abbr>NFT</abbr>)<sup id=\"retfn1\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn1\" aria-label=\"footnote\">1</a></sup>&nbsp;airdrop<sup id=\"retfn2\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn2\" aria-label=\"footnote\">2</a></sup>&nbsp;feature embedded in non-custodial wallets,<sup id=\"retfn3\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn3\" aria-label=\"footnote\">3</a></sup>&nbsp;which is disguised as free rewards or incentives for Hedera Hashgraph network users. The&nbsp;<dfn style=\"font-style: unset;\">Hedera Hashgraph</dfn>&nbsp;is the distributed ledger used by Hedera. The airdrop feature was originally created by the Hedera Hashgraph network for marketing purposes; however, cyber criminals can exploit this tactic to collect victim data to steal cryptocurrency.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">NFT Airdrop Defrauding Techniques</h2><h3 style=\"font-size: medium;\">Memos</h3><p>For a user to receive a token in their wallet as part of the airdrop process, the user must either hold the specific token offered, be a part of the community, or simply own a non-custodial wallet. Once the transaction is completed, and the user receives unsolicited or promotional cryptocurrency tokens and rewards in their non-custodial wallet as part of the airdrop process, a plaintext \"memo\" section appears that may be used to provide additional context about the transaction, including a reference number. Within these memos, users are required to click the embedded uniform resource locator (<abbr>URL</abbr>) to accept the tokens or rewards. The memo is independent of the wallet a user may use to manage their cryptocurrency; however, cyber criminals are compromising this memo feature and including a URL to a third-party website. This URL, links the user\'s cryptocurrency wallet to the website\'s decentralized applications (<abbr>dApps</abbr>)<sup id=\"retfn4\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn4\" aria-label=\"footnote\">4</a></sup>&nbsp;function to earn additional cryptocurrency; this connection often requires the user to input their login and security information, including seed phrases<sup id=\"retfn5\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn5\" aria-label=\"footnote\">5</a></sup>&nbsp;to complete the connection. This information entered by the user, allows the cyber criminal to steal the user\'s cryptocurrency from their wallet.</p><h3 style=\"font-size: medium;\">Social Media, Third Party Sites, and Phishing Emails</h3><p>Cyber criminals may also advertise malicious phishing<sup id=\"retfn6\"><a href=\"https://www.ic3.gov/PSA/2025/PSA250603#fn6\" aria-label=\"footnote\">6</a></sup>&nbsp;URLs for fraudulent NFT airdrop rewards tokens on social media or through a third-party website. Other cyber criminals may send a phishing email to cryptocurrency users offering an airdrop of free tokens. When a user clicks the link to visit the site, the URL connects to the user\'s wallet or the user will be directed to provide their password and/or link their wallet to receive the tokens. The cyber criminal then accesses the user\'s wallet, without authorization, and moves the user\'s cryptocurrency to a wallet owned by the cyber criminal, draining the user\'s wallet of cryptocurrency.</p></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Tips on How to Protect Yourself</h2><ul><li>If you did not sign up to participate in a marketing or rewards program with the provider and you receive an offer for free tokens, verify the offer is from the cryptocurrency provider before accepting and/or providing any information.</li><li style=\"margin-top: 0.5rem;\"><div>Do not respond to requests to provide personally identifying information, like passwords, seed phrases, or one-time passwords sent to your accounts if you did not initiate the outreach. Initiate a new call to the company using the verified customer service number if a \"representative\" reaches out to you via phone or email soliciting personal information.</div><ul><li>Do not click links or use numbers provided in suspicious emails for confirmation communication is legitimate. Use verified customer service numbers provided by the company on official communications.</li></ul></li><li style=\"margin-top: 0.5rem;\">Monitor cryptocurrency accounts for suspicious login attempts, unauthorized changes to the account, unrecognized transactions, or compromised credentials.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Victim Reporting and Additional Information</h2><p>If you suspect that you or someone you know are a victim of a Hedera Hashgraph network cryptocurrency scam:</p><ul><li>Contact your account providers immediately to regain control of your accounts, change passwords, and place alerts on your accounts for suspicious login attempts and/or transactions.</li><li style=\"margin-top: 0.5rem;\">Be cautious of individuals or companies claiming they can assist in recovering funds lost in scams, as this may be an additional scam.</li><li style=\"margin-top: 0.5rem;\"><div>Submit a report with as much detail as possible to the FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>.</div><ul><li><div>The most important information you can include in the report are transaction details, which includes:</div><ul><li>Cryptocurrency addresses</li><li style=\"margin-top: 0.5rem;\">Amount and type of cryptocurrency</li><li style=\"margin-top: 0.5rem;\">Date and time</li><li style=\"margin-top: 0.5rem;\">Transaction ID (hash)</li></ul></li><li style=\"margin-top: 0.5rem;\"><div>For additional information, please see:</div><ul><li>FBI Public Service Announcement FBI Guidance for Cryptocurrency Scam Victims, Alert Number I-082423-PSA:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2023/PSA230824\">www.ic3.gov/PSA/2023/PSA230824</a></li><li style=\"margin-top: 0.5rem;\">FBI IC3 Cryptocurrency Crime Guidance:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/CrimeInfo/Cryptocurrency\">www.ic3.gov/CrimeInfo/Cryptocurrency</a></li></ul></li></ul></li></ul></section></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup><dfn>Nonfungible Tokens</dfn>&nbsp;(NFTs) are blockchain-based tokens that each represent a unique asset like a piece of art, digital content, or media. An NFT can be thought of as an irrevocable digital certificate of ownership and authenticity for a given asset, whether digital or physical. NFTs cannot be traded or exchanged at equivalency.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn1\" title=\"Jump back to footnote 1 in the text\">↩</a></p><p id=\"fn2\"><sup>2</sup>An&nbsp;<dfn>airdrop</dfn>&nbsp;is a campaign that some companies or people do when launching a token. It consists of giving away a certain amount of this token to a select group of people to gain popularity.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn2\" title=\"Jump back to footnote 2 in the text\">↩</a></p><p id=\"fn3\"><sup>3</sup>A&nbsp;<dfn>non-custodial wallet</dfn>, often referred to as a&nbsp;<dfn>self-custody wallet</dfn>, is a cryptocurrency wallet where the user has full control over their private keys and assets.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn3\" title=\"Jump back to footnote 3 in the text\">↩</a></p><p id=\"fn4\"><sup>4</sup>A&nbsp;<dfn>dApp</dfn>&nbsp;is an application that can operate autonomously, typically through the use of smart contracts, that run on a decentralized computing, blockchain, or another distributed ledger system.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn4\" title=\"Jump back to footnote 4 in the text\">↩</a></p><p id=\"fn5\"><sup>5</sup>A&nbsp;<dfn>seed phrase</dfn>&nbsp;is a string of 12 to 24 words that serve as the key to a user\'s crypto. It is a series of words generated by the user\'s cryptocurrency wallet that gives them access to the crypto associated with that wallet.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn5\" title=\"Jump back to footnote 5 in the text\">↩</a></p><p id=\"fn6\"><sup>6</sup><dfn>Phishing</dfn>&nbsp;is an attempt to trick users into clicking on a malicious link or opening an email attachment as a means to compromise their computer.&nbsp;<a href=\"https://www.ic3.gov/PSA/2025/PSA250603#retfn6\" title=\"Jump back to footnote 6 in the text\">↩</a></p></footer>', 2025, '2025-06-03', '', '', 1748880000, 1766535300);
INSERT INTO `ic3_psa` (`id`, `code`, `title`, `content`, `publish_year`, `publish_date`, `file_zh`, `file_tw`, `createtime`, `updatetime`) VALUES
(28, 'PSA250515', 'Senior US Officials Impersonated in Malicious Messaging Campaign', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><abbr title=\"Federal Bureau of Investigation\" style=\"text-decoration-line: none; text-decoration-style: initial;\">FBI</abbr>&nbsp;is issuing this announcement to warn and provide mitigation tips to the public about an ongoing malicious text and voice messaging campaign. Since April 2025, malicious actors have impersonated senior US officials to target individuals, many of whom are current or former senior US federal or state government officials and their contacts. If you receive a message claiming to be from a senior US official, do not assume it is authentic.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Specific Campaign Details</h2><p>The malicious actors have sent text messages and AI-generated voice messages — techniques known as smishing and vishing, respectively — that claim to come from a senior US official in an effort to establish rapport before gaining access to personal accounts. One way the actors gain such access is by sending targeted individuals a malicious link under the guise of transitioning to a separate messaging platform. Access to personal or official accounts operated by US officials could be used to target other government officials, or their associates and contacts, by using trusted contact information they obtain. Contact information acquired through social engineering schemes could also be used to impersonate contacts to elicit information or funds.</p><blockquote class=\"smishing\" style=\"border-top: 4px solid rgb(0, 0, 255); border-right: none; border-bottom: 4px solid rgb(0, 0, 255); border-left: none; border-image: initial; padding: 0.5em; background: unset; color: rgb(0, 0, 255);\"><p>\"<dfn style=\"font-style: normal;\">Smishing</dfn>\" is the malicious targeting of individuals using Short Message Service (<abbr>SMS</abbr>) or Multimedia Message Service (<abbr>MMS</abbr>) text messaging. \"<dfn style=\"font-style: normal;\">Vishing</dfn>\", which may incorporate AI-generated voices, is the malicious targeting of individuals using voice memos. Both smishing and vishing use tactics similar to spear phishing, which uses email to target specific individuals or groups.</p></blockquote></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Smishing, Vishing, and Spear Phishing Are Common Criminal Tactics</h2><p>Traditionally, malicious actors have leveraged smishing, vishing, and spear phishing to transition to a secondary messaging platform where the actor may present malware or introduce hyperlinks that direct intended targets to an actor-controlled site that steals log-in information, like user names and passwords. For smishing, malicious actors typically use software to generate phone numbers that are not attributed to a specific mobile phone or subscriber to engage with a target by masquerading as an associate or family member. For vishing, malicious actors are more frequently exploiting AI-generated audio to impersonate well-known, public figures or personal relations to increase the believability of their schemes.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Recommendations</h2><p>The following guidance can be used to identify a suspicious message and help protect yourself from this campaign.</p><section><h3 style=\"font-size: medium;\">Spotting a Fake Message</h3><ul><li>Verify the identity of the person calling you or sending text or voice messages. Before responding, research the originating number, organization, and/or person purporting to contact you. Then independently identify a phone number for the person and call to verify their authenticity.</li><li style=\"margin-top: 0.5rem;\">Carefully examine the email address; messaging contact information, including phone numbers;&nbsp;<abbr title=\"uniform resource locators\" style=\"text-decoration-line: none; text-decoration-style: initial;\">URLs</abbr>; and spelling used in any correspondence or communications. Scammers often use slight differences to deceive you and gain your trust. For instance, actors can incorporate publicly available photographs in text messages, use minor alterations in names and contact information, or use AI-generated voices to masquerade as a known contact.</li><li style=\"margin-top: 0.5rem;\">Look for subtle imperfections in images and videos, such as distorted hands or feet, unrealistic facial features, indistinct or irregular faces, unrealistic accessories such as glasses or jewelry, inaccurate shadows, watermarks, voice call lag time, voice matching, and unnatural movements.</li><li style=\"margin-top: 0.5rem;\">Listen closely to the tone and word choice to distinguish between a legitimate phone call or voice message from a known contact and AI-generated voice cloning, as they can sound nearly identical.</li><li style=\"margin-top: 0.5rem;\">AI-generated content has advanced to the point that it is often difficult to identify. When in doubt about the authenticity of someone wishing to communicate with you, contact your relevant security officials or the FBI for help.</li></ul></section><section><h3 style=\"font-size: medium;\">How to Protect Yourself from Potential Fraud or Loss of Sensitive Information</h3><ul><li>Never share sensitive information or an associate’s contact information with people you have met only online or over the phone. If contacted by someone you know well via a new platform or phone number, verify the new contact information through a previously confirmed platform or trusted source.</li><li style=\"margin-top: 0.5rem;\">Do not send money, gift cards, cryptocurrency, or other assets to people you do not know or have met only online or over the phone. If someone you know (or an associate of someone you know) requests that you send money or cryptocurrency, independently confirm contact information prior to taking action. Also, critically evaluate the context and plausibility of the request.</li><li style=\"margin-top: 0.5rem;\">Do not click on any links in an email or text message until you independently confirm the sender\'s identity.</li><li style=\"margin-top: 0.5rem;\">Be careful what you download. Never open an email attachment, click on links in messages, or download applications at the request of or from someone you have not verified.</li><li style=\"margin-top: 0.5rem;\">Set up two-factor (or multi-factor) authentication on any account that allows it, and never disable it. Actors may use social engineering techniques to convince you to disclose a two-factor authentication code, which allows the actor to compromise and take over accounts. Never provide a two-factor code to anyone over email, SMS/MMS text message or encrypted messaging application.</li><li style=\"margin-top: 0.5rem;\">Create a secret word or phrase with your family members to verify their identities</li></ul></section><section><h3 style=\"font-size: medium;\">Victim Reporting and Additional Information</h3><ul><li>For additional information, see FBI\'s guidance on&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/how-we-can-help-you/scams-and-safety/common-frauds-and-scams/spoofing-and-phishing\">Spoofing and Phishing</a>&nbsp;as well as a previous Public Service Announcement about how \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA241203\">Criminals Use Generative Artificial Intelligence to Facilitate Financial Fraud</a>.\" Cybersecurity and Infrastructure Security Agency (<abbr>CISA</abbr>) has published the following resources \"<a target=\"_blank\" href=\"https://www.cisa.gov/resources-tools/resources/phishing-guidance-stopping-attack-cycle-phase-one\">Phishing Guidance: Stopping the Attack Cycle at Phase One | CISA</a>\" and \"<a target=\"_blank\" href=\"https://www.cisa.gov/secure-our-world/teach-employees-avoid-phishing\">Teach Employees to Avoid Phishing | CISA</a>.\"</li></ul></section></section><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">If you believe you have been the victim of the campaign described above, contact your relevant security officials and the FBI. The FBI requests victims report any incident to your local&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">FBI Field Office</a>&nbsp;or the Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much detailed information as possible.</p>', 2025, '2025-05-15', '', '', 1747238400, 1766535385),
(29, 'PSA250513', 'Impersonation Scheme Targeting Middle Eastern Students in the United States', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The&nbsp;<abbr title=\"Federal Bureau of Investigation\" style=\"text-decoration-line: none; text-decoration-style: initial;\">FBI</abbr>&nbsp;is warning the public about a fraud scheme targeting foreign individuals lawfully residing in the United States on valid student visas. Criminal scammers impersonate US and foreign government officials claiming there is an issue with the student\'s immigration status and exploit this for financial gain. Thus far, we are aware scammers have targeted students from the United Arab Emirates (<abbr>UAE</abbr>), Saudi Arabia, Qatar, and Jordan.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">How The Scheme Works</h2><p>Scammers contact foreign students lawfully studying in the United States, or who are in the process of coming to the United States and impersonate government or immigration officials claiming the student is out of status for violations of F-1 student visa requirements or otherwise facing immigration issues. Victims are threatened with prosecution or deportation and asked to pay an unknown entity or bank account to process immigration paperwork, pay university registration fees, or pay a legal fee.</p><p>These scammers represent themselves as agents from Department of Homeland Security (<abbr>DHS</abbr>), Homeland Security Investigations (<abbr>HSI</abbr>), or US Citizenship and Immigration Services (<abbr>USCIS</abbr>) to increase the credibility of the scam.</p><p>In some instances, the scammers vary this scheme by presenting themselves as government officials from foreign countries, including UAE and Qatar. Diplomats from the UAE Embassy in Washington, DC, have been impersonated as well.</p><p>Scammers have also used fictitious names that sound like government agencies, impersonate US universities, and send links to fake websites.</p><p>Scammers may spoof the phone number of government agencies, foreign embassies, or universities. They may speak professionally and use the accents and/or language matching the purported location of the callers.</p><p>In 2024, government impersonation fraud schemes such as this cost the American public over $405 million in losses from over 17,000 complaints. Victims are often asked to pay a fee because of the scam via cryptocurrency, prepaid card/gift cards, or wire transfers.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li>Beware of unsolicited communication from someone purporting to be from the government, especially by phone. Verify you are speaking with a government official by hanging up and contacting the office through a third-party obtained number (eg. web search for legitimate contact information), then asking for the agent or department you were speaking with.</li><li style=\"margin-top: 0.5rem;\">Verify that the website visited is a secure or encrypted site, as government websites are.</li><li style=\"margin-top: 0.5rem;\">Repeating top level domains in a URL is a common scam to make a website appear legitimate (e.g. \"gov.org\" in a URL is a spoof of the .gov top level domain).</li><li style=\"margin-top: 0.5rem;\">Do not provide information on the phone until you verify the identity of the caller.</li><li style=\"margin-top: 0.5rem;\">If you believe you are the target of a government impersonation scam targeting foreign students, gather all relevant documentation and contact diplomatic security at your home country\'s embassy, the FBI, or Bureau of Diplomatic Security at the Department of State.</li><li style=\"margin-top: 0.5rem;\">Do not give anyone a two-factor authentication code used to log-in to an account or device.</li><li style=\"margin-top: 0.5rem;\">Do not download files to your phone or computer unless you have verified the source.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>The FBI requests the public report these fraudulent or suspicious activities to the FBI at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much information as possible:</p><ul><li>The name of the person or company that contacted you, the government agency they purport to be with, and their purported location.</li><li style=\"margin-top: 0.5rem;\">Dates, times, and location of communication and payments.</li><li style=\"margin-top: 0.5rem;\">Methods of communication used, including websites, emails, and telephone numbers.</li><li style=\"margin-top: 0.5rem;\">Any applications you may have downloaded or provided permissions to on your electronic device.</li><li style=\"margin-top: 0.5rem;\">Payment information provided to you and documentation of funds sent.</li><li style=\"margin-top: 0.5rem;\">Do not delete records of text conversations or emails as these may be requested by law enforcement.</li><li style=\"margin-top: 0.5rem;\">Contact your bank immediately to attempt to recall any identified fraudulent wire transfers and ask the bank to contact the FBI to start the Financial Fraud Kill Chain.</li></ul></section>', 2025, '2025-05-13', '', '', 1747065600, 1766536200),
(30, 'PSA250507', 'Cyber Criminal Proxy Services Exploiting End of Life Routers', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is issuing this announcement to inform individuals and businesses about proxy services taking advantage of end of life routers that are susceptible to vulnerabilities. When a hardware device is&nbsp;<dfn style=\"font-style: normal;\">end of life</dfn>, the manufacturer no longer sells the product and is not actively supporting the hardware, which also means they are no longer releasing software updates or security patches for the device. Routers dated 2010 or earlier likely no longer receive software updates issued by the manufacturer and could be compromised by cyber actors exploiting known vulnerabilities.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">End of life routers were breached by cyber actors using variants of TheMoon malware botnet. Recently, some routers at end of life, with remote administration turned on, were identified as compromised by a new variant of TheMoon malware. This malware allows cyber actors to install proxies on unsuspecting victim routers and conduct cyber crimes anonymously.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Proxies and Router Vulnerabilities</h2><p>A proxy server is a system or router that provides a gateway between users and the Internet. It is an intermediary between end-users and the web pages they visit online. A proxy is a service that relays users\' Internet traffic while hiding the link between users and their activity.</p><p>Cyber actors use proxy services to hide their identities and location. When actors use a proxy service to visit a website to conduct criminal activity, like stealing cryptocurrency or contracting illegal services, the website does not register their real IP address and instead registers the proxy IP.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">TheMoon Malware</h2><p>TheMoon malware was first discovered on compromised routers in 2014 and has since gone through several campaigns. TheMoon does not require a password to infect routers; it scans for open ports and sends a command to a vulnerable script. The malware contacts the command and control (<abbr>C2</abbr>) server and the C2 server responds with instructions, which may include instructing the infected machine to scan for other vulnerable routers to spread the infection and expand the network.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><p>Commonly identified signs of malware infections on routers include overheating devices, problems with connectivity, and changes to settings the administrator does not recognize.</p><p>The FBI recommends individuals and companies take the following precautions:</p><ul><li>If the router is at end of life, replace the device with an updated model if possible.</li><li style=\"margin-top: 0.5rem;\">Immediately apply any available security patches and/or firmware updates for your devices.</li><li style=\"margin-top: 0.5rem;\">Login online to the router settings and disable remote management/remote administration, save the change, and reboot the router.</li><li style=\"margin-top: 0.5rem;\">Use strong passwords that are unique and random and contain at least 16 but no more than 64 characters. Avoid reusing passwords and disable password hints.</li><li style=\"margin-top: 0.5rem;\">If you believe there is suspicious activity on any device, apply any necessary security and firmware updates, change your password, and reboot the router.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Victim Reporting and Additional Information</h2><p>If you suspect you are a victim of a proxy service or your personal information has been compromised:</p><ul><li>File a complaint with the FBI Internet Crime Complaint Center (<abbr>IC3</abbr>),&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. When available, please include the following information regarding the incident: date, time, and location of the incident; type of activity; number of people affected; type of equipment used for the activity; the name of the submitting organization; designated point of contact.</li><li style=\"margin-top: 0.5rem;\">Contact your account provider immediately to regain control of your accounts, change passwords, and place alerts on your accounts for suspicious login attempts and/or transactions.</li></ul></section>', 2025, '2025-05-07', '', '', 1746547200, 1766537792),
(31, 'PSA250430', 'Emerging Discount Medical Insurance Scams', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) warns the public of discount medical insurance scams. Discount medical insurance scams involve misleading or fraudulent offers for medical insurance plans that promise reduced rates on legitimate medical insurance but do not provide any actual medical insurance coverage, resulting in millions of dollars in losses annually. These scams often target people who are looking for more affordable healthcare options and use misleading tactics such as stating to be a legitimate medical insurance provider, pressuring people to sign up quickly due to time limited special rates, or promising free services with hidden fees to lure people to sign up. A typical discount medical insurance scam begins with unsolicited contact via calls, texts, or emails from unknown businesses offering special deals or discounted medical insurance.</p><ul><li><p>Washington state issued a cease-and-desist order against a discount medical insurance company after receiving over 100 complaints of fraudulent practices. The company misrepresented their plan coverage options and did not cover medical costs, which left beneficiaries paying out of pocket in full for medical costs they had been led to believe would be at least partially covered. Victims also did not receive refunds after cancelling their insurance plans as the discount medical insurance company had promised, and the company made unauthorized charges to victims\' bank accounts. The company was conducting business under multiple names and was responsible for the following examples.<sup id=\"retfn1\"><a aria-label=\"footnote\" href=\"https://www.ic3.gov/PSA/2025/PSA250430#fn1\">1</a></sup></p><ul><li>A couple from Pennsylvania was pressured to sign up for a discount medical insurance plan through what they believed was a national provider. The couple was told to act quickly, or they would lose the temporarily discounted price for the plan. Following an emergency room visit and an appointment with their primary care physician, the couple received an explanation of benefits stating they were responsible for all medical bills as the medical services received by the couple were not covered by their policy.</li><li style=\"margin-top: 0.5rem;\">Another individual from Pennsylvania was contacted by a healthcare representative claiming that their company could offer a much cheaper plan than the one the individual had. The individual was told he would receive a refund for his current plan once he signed up for the new plan but did not receive any information regarding the refund. The representative indicated the individual had to act quickly or lose the deep discount. After purchasing the new healthcare plan, the individual never received the promised refund and was unable to get any information from the new insurance company.</li></ul></li><li style=\"margin-top: 0.5rem;\">An individual in Texas responded to an advertisement offering aid for gasoline and groceries to senior citizens. He was told he had to sign up for a dental policy with a specific insurance company to obtain the aid. After he signed up, he tried to cancel the dental insurance policy but was told by customer service to request the cancellation via email. The insurance company did not respond to his emails requesting to cancel his dental insurance policy, and he had to cancel his credit card to stop the charges.</li><li style=\"margin-top: 0.5rem;\">An individual in Maryland was told he would save thousands of dollars by purchasing a health insurance policy and paying for the entire year up front. He was told the new policy would cover his current medical providers and hospitals, and he would only be responsible for a $20 co-pay per doctor\'s office visit and $50 per urgent care visit. After needing emergency surgery, the hospital informed him that they did not accept his new health insurance, and he was responsible for the $7000 cost of the surgery.</li></ul><section><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li>Always make sure the medical plan offered is from a reputable source, and that the company is licensed to operate in your state. The state insurance commissioner or the Better Business Bureau are good sources to verify the veracity of a plan.</li><li style=\"margin-top: 0.5rem;\">Verify with current providers that they accept the insurance plan you are considering.</li><li style=\"margin-top: 0.5rem;\">If no policy documents are sent, this could be a sign of a fraudulent plan. If policy documents are sent, review them and read the fine print. Understand exactly what is being offered before committing to anything.</li><li style=\"margin-top: 0.5rem;\">Don\'t pay anything upfront. Be cautious if a company asks for large upfront payments or seems to be pressuring you into making quick decisions.</li><li style=\"margin-top: 0.5rem;\">Do your own research. If the plan seems too good to be true, it probably is.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>If you believe you have been a victim of as similar fraudulent activity, please file a report with the FBI\'s Internet Crimes Complaint Center at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much information as possible, such as identifying information about the company and or healthcare provider who sold the fraudulent medical insurance to you including name, phone number, address, email address, and website.</p><p>If you have questions about Medicare reach out to them at&nbsp;<a target=\"_blank\" href=\"https://www.medicare.gov/\">www.Medicare.gov</a>&nbsp;or call at&nbsp;<a href=\"tel:+1(800)633-4227\">1-800-MEDICARE</a>&nbsp;(1-800-633-4227)</p></section></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup>&nbsp;Press release | Office of the Insurance Commissioner Washington State | \"<cite>Kuderer issues warning on sham health insurers after Quick Health investigation</cite>\" | 29 January 2025 |&nbsp;<a target=\"_blank\" href=\"https://www.insurance.wa.gov/news/Kuderer-issues-warning-sham-health-insurers-after-quick-health-investigation\">https://www.insurance.wa.gov/news/Kuderer-issues-warning-sham-health-insurers-after-quick-health-investigation</a>&nbsp;| Accessed 24 February 2025.&nbsp;<a title=\"Jump back to footnote 1 in the text\" href=\"https://www.ic3.gov/PSA/2025/PSA250430#retfn1\">↩</a></p></footer>', 2025, '2025-04-30', '', '', 1745942400, 1766537870),
(32, 'PSA250429', 'Threat Actors Use \"Swatting\" to Target Victims Nationwide', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is aware of multiple recent \"swatting\" incidents. This Public Service Announcement (<abbr>PSA</abbr>) is intended to provide the public with information about what swatting is, how to take protective steps against swatting, and how to report potential incidents. The FBI takes swatting threats seriously and coordinates with federal, state, local, tribal, and territorial law enforcement partners to respond to and investigate these incidents.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">What is Swatting?</h2><p><dfn style=\"font-style: unset;\">Swatting</dfn>&nbsp;is the malicious tactic of making hoax calls or reports to emergency services, typically feigning an immediate threat to life. Swatting is intended to draw a large response from&nbsp;<abbr title=\"Special Weapons and Tactics\" style=\"text-decoration: unset;\">SWAT</abbr>&nbsp;teams or other law enforcement resources to an unsuspecting victim’s location, causing chaos and the potential for injury or violence.</p><p>Targets of swatting often include high-profile public figures, as well as schools, hospitals, places of worship, and centers of mass transportation, but anyone can be a victim. A swatting incident may be an isolated event targeting one victim or part of a larger coordinated effort to target multiple victims.</p><p>Swatting may be conducted to harass, intimidate, or retaliate against intended targets. It is a serious crime that can have deadly consequences due to confusion on the part of victims and responding officials, and that also diverts limited public safety resources from valid emergencies.</p><p>Threat actors often compile sensitive information from a wide range of publicly available sources, including online accounts, to develop invasive profiles of their targets. They leverage spoofing technology to anonymize their identities, using phone numbers, email addresses, and social media profiles to make it appear the false report is coming from the victim. Threat actors may also use compromised smart home devices to facilitate swatting attacks.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Ways to Protect Yourself</h2><p>The FBI urges the public to consider the following measures:</p><ul><li>Review your online presence for sensitive personal information that could enable malicious actors to conduct a swatting attack.</li><li style=\"margin-top: 0.5rem;\">Exercise care when posting content (including photos and videos) or sharing it with individuals online. Although seemingly innocuous, images and videos can be exploited or manipulated by malicious actors for criminal activity.</li><li style=\"margin-top: 0.5rem;\">Consider online resources and services that may aid in reducing or removing sensitive publicly available information.</li><li style=\"margin-top: 0.5rem;\">Use strong, unique passwords, and multi-factor authentication on all devices and accounts, including smart home devices.</li><li style=\"margin-top: 0.5rem;\">Discuss swatting with your family members or colleagues and have a plan in place in the event of law enforcement contact at your residence, business, or other location.</li></ul><p>In the event you are the victim of a swatting attack, stay calm, and listen to and cooperate with responding law enforcement.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Additional Resources</h2><p>If you believe you are the victim of a swatting incident, retain all information regarding the incident, such as usernames, email addresses, websites, or names of platforms used for communication, photos, or videos.</p><ul><li>Immediately report it to your local law enforcement agency.</li><li style=\"margin-top: 0.5rem;\">To report an emergency or an immediate threat to life, call 911.</li><li style=\"margin-top: 0.5rem;\">To report any leads, threats, and/or criminal activity you may also visit&nbsp;<a target=\"_blank\" href=\"https://tips.fbi.gov/\">tips.fbi.gov</a>, call&nbsp;<a href=\"tel:+1(800)225-5324\">1-800-CALL-FBI</a>&nbsp;(225-5324) or contact your local FBI field office&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us\">https://www.fbi.gov/contact-us</a>.</li></ul></section>', 2025, '2025-04-29', '', '', 1745856000, 1766537956),
(33, 'PSA250424', 'FBI Seeking Tips about PRC-Targeting of US Telecommunications', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><abbr title=\"Federal Bureau of Investigation\" style=\"text-decoration: unset;\">FBI</abbr>&nbsp;is issuing this announcement to ask the public to report information about&nbsp;<abbr title=\"People\'s Republic of China\" style=\"text-decoration: unset;\">PRC</abbr>-affiliated activity publicly tracked as \"Salt Typhoon\" and the compromise of multiple US telecommunications companies, especially information about specific individuals behind the campaign. Investigation into these actors and their activity revealed a broad and significant cyber campaign to leverage access into these networks to target victims on a global scale. This activity resulted in the theft of call data logs, a limited number of private communications involving identified victims, and the copying of select information subject to court-ordered US law enforcement requests.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">FBI and US Government partners have previously released public statements on Salt Typhoon activity on&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/news/press-releases/joint-statement-by-fbi-and-cisa-on-peoples-republic-of-china-activity-targeting-telecommunications\">25 October 2024</a>&nbsp;and&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/news/press-releases/joint-statement-from-fbi-and-cisa-on-the-peoples-republic-of-china-targeting-of-commercial-telecommunications-infrastructure\">13 November 2024</a>, and published the guide, \"<a target=\"_blank\" href=\"https://www.ic3.gov/CSA/2024/241203.pdf\">Enhanced Visibility and Hardening Guidance for Communications Infrastructure</a>,\" on 3 December 2024.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">FBI maintains its commitment to protecting the US telecommunications sector and the individuals and organizations targeted by Salt Typhoon by identifying, mitigating, and disrupting Salt Typhoon\'s malicious cyber activity. If you have any information about the individuals who comprise Salt Typhoon or other Salt Typhoon activity, we would particularly like to hear from you.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">In addition, the U.S. Department of State\'s&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/rewardsforjustice.net/443/rewards%E2%81%84foreign-malicious-cyber-activity-against-u-s-critical-infrastructure%E2%81%84/0DF76CD35FC9C00840F00393FA620159AA78468DCCEEA3BDC9AD0228F1CFE7D6\">Rewards for Justice (<abbr>RFJ</abbr>) program</a>&nbsp;is offering a reward of up to $10 million (<abbr title=\"United States Dollars\" style=\"text-decoration: unset;\">USD</abbr>) for information about foreign government-linked individuals participating in certain malicious cyber activities against US critical infrastructure in violation of the Computer Fraud and Abuse Act (<abbr>CFAA</abbr>).</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">If you have any information on Salt Typhoon, contact your local FBI field office, file a report on the FBI\'s Internet Crime Complaint Center at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>, or submit your tip to RFJ on Signal at +1-202-702-7843 or via the RFJ Tor-based tip line: he5dybnt7sr6cm32xt77pazmtm65flqy6irivtflruqfc5ep7eiodiad.onion (Tor browser required).</p>', 2025, '2025-04-24', '', '', 1745424000, 1766590758),
(35, 'PSA250418', 'FBI Warns of Scammers Impersonating the IC3', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) warns the public about an ongoing fraud scheme where criminal scammers are impersonating FBI Internet Crime Complaint Center (<abbr>IC3</abbr>) employees to deceive and defraud individuals. Between December 2023 and February 2025, the FBI received more than 100 reports of IC3 impersonation scams.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">How It Works</h2><p>Complainants report initial contact from the scammers can vary. Some individuals received an email or a phone call, while others were approached via social media or forums. Almost all complainants indicated the scammers claimed to have recovered the victim\'s lost funds or offered to assist in recovering funds. However, the claim is a ruse to revictimize those who have already lost money to scams.</p><p>A recent example of the impersonation scheme variant indicates scammers create female persona profiles on social media networking sites and join groups for financial fraud victims, representing themselves as fellow financial fraud victims. Scammers then recommend actual victims reach out to male persona, \"Jaime Quin\" (Quin), the alleged \"Chief Director\" of IC3, via Telegram. Once contacted, \"Quin\" claims to have recovered the lost funds, but uses this as a ruse to gain access to their financial information and revictimize them.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li>The IC3 will never directly communicate with individuals via phone, email, social media, phone apps, or public forums. If further information is needed, individuals will be contacted by FBI employees from local field offices or other law enforcement officers.</li><li style=\"margin-top: 0.5rem;\">Scammers will change aliases and tactics; however, the scheme generally remains the same.</li><li style=\"margin-top: 0.5rem;\">Never share sensitive information with people you have met only online or over the phone.</li><li style=\"margin-top: 0.5rem;\">The IC3 will not ask for payment to recover lost funds, nor will they refer a victim to a company requesting payment for recovering funds.</li><li style=\"margin-top: 0.5rem;\">Do not send money, gift cards, cryptocurrency, or other assets to people you do not know or have met only online or over the phone.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>The FBI requests victims immediately report fraudulent or suspicious activity to the FBI IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much information as possible:</p><ul><li>Identifying information about the person or company that contacted you.</li><li style=\"margin-top: 0.5rem;\">Methods of communication used, including websites, emails, and telephone numbers.</li><li style=\"margin-top: 0.5rem;\">Financial transaction information, such as the date, type of payment, amount, account numbers involved, the name and address of the receiving financial institution, and receiving cryptocurrency addresses.</li><li style=\"margin-top: 0.5rem;\">Description of your interaction with the individual, including how contact was initiated, such as the type of communication, purpose of the request for money, how you were told or instructed to make payment, what information you provided to the scammer, and any other details pertinent to your complaint.</li></ul><p>Victims aged 60 or over who need assistance filing an IC3 complaint can contact the&nbsp;<abbr title=\"Department of Justice\" style=\"text-decoration: unset;\">DOJ</abbr>&nbsp;Elder Justice Hotline, 1-833-FRAUD-11 (or&nbsp;<a href=\"tel:+1(833)372-8311\">833-372-8311</a>).</p></section><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">For additional information on similar scams, please see previous Public Service Announcements:</p><ul style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><li>IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2022/PSA220307\">FBI Warns of the Impersonation of Law Enforcement and Government Officials</a>\"</li><li style=\"margin-top: 0.5rem;\">IC3 | \"<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2022/PSA221110\">Scammers Using Computer-Technical Support Impersonation Scams to Target Victims and Conduct Wire Transfers</a>\"</li></ul>', 2025, '2025-04-18', '', '', 1744905600, 1766590855),
(36, 'PSA250402', 'Criminal Actors Steal US Taxpayer Identity to File False Tax Returns and Claim Refunds', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FBI is warning the public about criminal actors stealing US taxpayer identities to file false tax returns and fraudulently claim refunds. The FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>) has received over 1,000 complaints about identity theft in connection with tax returns within the past year representing a 26% increase from the previous year. Stolen refunds are often redirected by criminal actors to accounts or addresses they control, including bank accounts, prepaid debit cards, mail drops and/or third-party accounts.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Prevent False Tax Filings</h2><p>The IRS recommends establishing an Identity Protection Personal Identification Number (<abbr>IP PIN</abbr>), a 6-digit number assigned to taxpayers to help prevent the misuse of a taxpayers\' Social Security number on fraudulent federal income tax returns. Once enrolled, a new IP PIN will be generated each year. Enrollment in the IP PIN program starts by establishing an online account at IRS.gov. If the taxpayer is a victim of tax identity theft, the IRS will automatically enroll the taxpayer into the IP PIN program. For further information on how to enroll in the IP PIN program go to:&nbsp;<a target=\"_blank\" href=\"https://www.irs.gov/identity-theft-fraud-scams/identity-theft-guide-for-individuals#steps\">https://www.irs.gov/identity-theft-fraud-scams/identity-theft-guide-for-individuals#steps</a>.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report Identity Theft</h2><p>The FBI requests taxpayers who suspect they have been a victim of identity theft, report the incident to the FBI IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>&nbsp;as quickly as possible. Additional information regarding identity theft may be found at&nbsp;<a target=\"_blank\" href=\"https://identitytheft.gov/\">identitytheft.gov</a>.</p></section>', 2025, '2025-04-02', '', '', 1743523200, 1766590897),
(37, 'PSA250321', 'Individuals Target Tesla Vehicles and Dealerships Nationwide with Arson, Gunfire, and Vandalism', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is informing the public of recent nationwide incidents targeting Tesla electric vehicles (<abbr>EV</abbr>), dealerships, storage lots, and charging stations. Since January 2025, incidents targeting Tesla EVs have occurred in at least nine states. These incidents have involved arson, gunfire, and vandalism, including graffiti expressing grievances against those the perpetrators perceive to be racists, fascists, or political opponents. These criminal actions appear to have been conducted by lone offenders, and all known incidents occurred at night.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">Individuals require little planning to use rudimentary tactics, such as improvised incendiary devices and firearms, and may perceive these attacks as victimless property crimes.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Recommendations</h2><p>The FBI urges the public to exercise vigilance and to look out for suspicious activity in areas occupied by Tesla dealerships or Tesla-related entities.</p><h3 style=\"font-size: medium;\">Potential Threat Activity:</h3><ul><li>Violent threats made online referencing specific Tesla properties</li><li style=\"margin-top: 0.5rem;\">Inquiring or examining security measures at Tesla dealerships</li><li style=\"margin-top: 0.5rem;\">Photography of security-related equipment or personnel at Tesla dealerships</li><li style=\"margin-top: 0.5rem;\">Unusual surveillance or interest in Tesla-related entities</li><li style=\"margin-top: 0.5rem;\">Attempts to gain access to restricted areas or bypass security measures at Tesla-related properties</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Resources</h2><ul><li>If there is an emergency, contact local law enforcement or 911 immediately.</li><li style=\"margin-top: 0.5rem;\">To report a threat, contact your local FBI field office (<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">https://www.fbi.gov/contact-us/field-offices</a>), call&nbsp;<a href=\"tel:+1(800)225-5324\">1-800-CALL-FBI</a>&nbsp;(225-5324), or visit&nbsp;<a target=\"_blank\" href=\"https://tips.fbi.gov/\">tips.fbi.gov</a>.</li><li style=\"margin-top: 0.5rem;\">Be aware of your surroundings at all times and report suspicious activities to the authorities.</li></ul><p>Reporting these crimes can help law enforcement identify violent or malicious actors and prevent further damage.</p></section>', 2025, '2025-03-21', '', '', 1742486400, 1766590952),
(38, 'PSA250306', 'Mail Scam Targeting Corporate Executives Claims Ties to Ransomware', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is issuing this announcement to inform businesses of a scam involving letters delivered in the mail from unidentified criminal actors to corporate executives, claiming to have come from a ransomware group.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">Stamped “Time Sensitive Read Immediately”, the letter claims the “BianLian Group” gained access into the organization’s network and stole thousands of sensitive data files. The letter then goes on to threaten that the victim’s data will be published to BianLian’s data leak sites if recipients do not use an included QR code linked to a Bitcoin wallet to pay between $250,000 and $500,000 within ten days from receipt of the letter, claiming the group will not negotiate further with victims.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">FBI assesses the letters are an attempt to scam organizations into paying a ransom. The letter contains a US-based return address of “BianLian Group” originating from Boston, Massachusetts. We have not yet identified any connections between the senders and the widely-publicized BianLian ransomware and data extortion group.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself:</h2><p>FBI recommends individuals take the following precautions:</p><ul><li>Notify corporate executives and the organization of the scam for awareness.</li><li style=\"margin-top: 0.5rem;\">Ensure employees are educated on what to do if they receive a ransom threat.</li><li style=\"margin-top: 0.5rem;\">If you or your organization receive one of these letters, ensure your network defenses are up to date and that there are no active alerts regarding malicious activity.</li><li style=\"margin-top: 0.5rem;\">If you discover you are a victim of BianLian ransomware, please visit our&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/CSA/2024/241120.pdf\">Joint Cybersecurity Awareness Bulletin</a>&nbsp;for recent tactics, techniques, and procedures and indicators of compromise to help organizations protect against ransomware.</li></ul></section><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">FBI requests victims report any incident to your local&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">FBI Field Office</a>&nbsp;or the&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">Internet Crime Complaint Center (<abbr>IC3</abbr>)</a>.</p>', 2025, '2025-03-06', '', '', 1741190400, 1766591420);
INSERT INTO `ic3_psa` (`id`, `code`, `title`, `content`, `publish_year`, `publish_date`, `file_zh`, `file_tw`, `createtime`, `updatetime`) VALUES
(41, 'PSA250305', 'Beijing Leveraging Freelance Hackers and Information Security Companies to Compromise Computer Networks Worldwide', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p><abbr title=\"Federal Bureau of Investigation\" style=\"text-decoration: unset;\">FBI</abbr>&nbsp;is releasing this Public Service Announcement to highlight that the Chinese government is using formal and informal connections with freelance hackers and information security (<abbr>InfoSec</abbr>) companies to compromise computer networks worldwide.</p><p>China\'s InfoSec ecosystem flourishes because China\'s government agencies, including its primary intelligence service the Ministry of State Security (<abbr>MSS</abbr>) and its domestic police agency the Ministry of Public Security (<abbr>MPS</abbr>), weaponize InfoSec companies by tasking companies that advertise legitimate cybersecurity services to also use their expertise to gain unauthorized access to victim networks to collect for China\'s intelligence services. This ecosystem of InfoSec companies and freelance hackers enables and encourages indiscriminate global cyber activity, while providing the Chinese government with a layer of plausible deniability.</p><p>Today, the&nbsp;<a target=\"_blank\" href=\"https://www.justice.gov/opa/pr/justice-department-charges-12-chinese-contract-hackers-and-law-enforcement-officers-global\">Southern District of New York</a>&nbsp;unsealed an indictment against eight employees of China-based InfoSec company Anxun Information Technology Co., Ltd.,&nbsp;<abbr title=\"also known as\" style=\"text-decoration: unset;\">aka</abbr>&nbsp;<abbr>i-Soon</abbr>, and two MPS officers who, at times, directed i-Soon activities in service of the Chinese government. i-Soon has been a key player in China\'s InfoSec ecosystem over the last decade, working with at least 43 separate MSS or MPS bureaus in 31 provinces and municipalities across China. The indicted i-Soon hackers sold stolen data to the MSS and MPS from a myriad of victims, to include US-based critics of the Chinese government and Chinese dissidents, a US news organization, a large US-based religious organization, multiple governments in Asia, and US federal and state government agencies. i-Soon sold information to China\'s intelligence and security services to suppress free speech and democratic processes worldwide, and target groups deemed a threat to the Chinese government. i-Soon also sold platforms to MSS and MPS customers for their own hacking efforts. i-Soon\'s activities are publicly tracked as Aquatic Panda, Red Alpha, Red Hotel, Charcoal Typhoon, Red Scylla, Hassium, Chromium, and TAG-22.</p><p>Also today, the District Court for the District of Columbia unsealed two indictments of freelance Chinese hackers Yin KeCheng and Zhou Shuai, who maintained ties to i-Soon and the Chinese government. Since 2011, Yin and Zhou have operated in China\'s InfoSec ecosystem and enriched themselves by selling stolen US information to the Chinese government. Zhou served for a period of time in i-Soon\'s Strategic Consulting Division. Yin, known in Chinese hacking circles for his prolific targeting of US entities, explained to an associate in 2013 that he wanted to \"mess with the American military\" and \"break into a big target,\" hoping the proceeds from selling the stolen US data would be enough to purchase a car. On at least one occasion, Yin compromised sensitive data which he turned over to Zhou, who partnered with an i-Soon employee to sell the stolen data. Yin and Zhou\'s activities are publicly tracked as APT27, Threat Group 3390, Bronze Union, Emissary Panda, Lucky Mouse, Iron Tiger, UTA0178, UNC 5221, and Silk Typhoon.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">Reporting</h2><p>If you suspect you have been a victim of malicious cyber activity by groups associated with the government of China, report the suspicious activity to the FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.IC3.gov</a>&nbsp;as quickly as possible</p></section></main>', 2025, '2025-03-05', '', '', 1741104000, 1766591812),
(42, 'PSA250228', 'Safety Concerns Related to Fraudulent Compounding Practices Associated with Weight Loss Drugs', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) warns the public of noncompliant healthcare providers, to include pharmacies, weight loss clinics, and medical spas, engaging in fraudulent compounding practices by unlawfully misrepresenting compounded weight loss drugs. These misrepresented drugs can pose safety risks and significant health consequences to patients, such as gastrointestinal disorders, nervous system disorders, cardiac disorders, psychiatric disorders, and death.</p><p>Noncompliant healthcare providers are selling fraudulently compounded drugs claiming to contain semaglutide, the active ingredient in Ozempic and Wegovy, in combination with other ingredients. Some healthcare providers are using compounded mixtures of unknown drugs that do not contain semaglutide, drugs with high levels of impurities, and unsafe or unapproved drugs.</p><ul><li>Healthcare professionals at medical spas, pharmacies and weight loss centers in multiple states sold fraudulently compounded semaglutide drugs. Testing of the compounded drugs revealed some of the misrepresented compounds did not contain semaglutide and had large percentages of unknown drug impurities.</li><li style=\"margin-top: 0.5rem;\">A southern-based medical spa and weight loss clinic offered and sold their own weight loss medication, which was compounded in Georgia. The compounded mixture had an \"animal grade\" semaglutide with vitamin B12, which is incompliant with&nbsp;<abbr title=\"Food and Drug Administration\" style=\"text-decoration: unset;\">FDA</abbr>&nbsp;regulations.</li><li style=\"margin-top: 0.5rem;\">A Southeastern state issued an Order of Summary Suspension<sup id=\"retfn1\"><a aria-label=\"footnote\" href=\"https://www.ic3.gov/PSA/2025/PSA250228#fn1\">1</a></sup>&nbsp;to an identified pharmacy due to alleged patient safety concerns. The pharmacy filled more than 1,000 prescriptions daily and employed many pharmacists and technicians with little to no pharmacy work experience. In the first seven months of 2023, the pharmacy generated millions of dollars by selling fraudulently compounded and generic versions of high dosages of semaglutide combined with vitamin B6 to healthcare providers.</li></ul><section><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li>Avoid suspiciously low prices of weight loss drugs sold by unlicensed healthcare providers.</li><li style=\"margin-top: 0.5rem;\">Be cautious when purchasing any pharmaceutical drugs online and buy only from licensed pharmacies.</li><li style=\"margin-top: 0.5rem;\">Consult with your medical provider before using any pharmaceutical weight loss drugs.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>If you believe you have been a victim of a similar fraudulent activity, please file a report with the FBI\'s Internet Crime Complaint Center at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. Be sure to include as much information as possible:</p><ul><li>Identifying information about the company and/or healthcare providers who sold fraudulent weight loss drugs to you, including name, phone number, address, email address, and website.</li><li style=\"margin-top: 0.5rem;\">State any side effects or complications related to the use of the weight loss drugs you received to FDA\'s MedWatch Safety Information and Adverse Event Reporting Program by completing and submitting a report online at&nbsp;<a target=\"_blank\" href=\"https://www.accessdata.fda.gov/scripts/medwatch/\">https://www.accessdata.fda.gov/scripts/medwatch/</a>. Additionally, the form can be downloaded at&nbsp;<a target=\"_blank\" href=\"https://www.fda.gov/media/85598/download?attachment\">https://www.fda.gov/media/85598/download?attachment</a>&nbsp;and submitted via fax at:&nbsp;<a href=\"tel:+1(800)332-0178\">1-800-FDA-0178</a>.</li><li style=\"margin-top: 0.5rem;\">If available, please include the National Provider Identifier (<abbr>NPI</abbr>) associated with the healthcare provider. The&nbsp;<dfn>NPI</dfn>&nbsp;is a 10-digit number that identifies covered healthcare providers for&nbsp;<abbr title=\"Health Insurance Portability and Accountability Act of 1996\" style=\"text-decoration: unset;\">HIPPA</abbr>&nbsp;transactions and can be found at&nbsp;<a target=\"_blank\" href=\"https://npiregistry.cms.hhs.gov/search\">https://npiregistry.cms.hhs.gov/search</a>.</li></ul></section></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup>&nbsp;An&nbsp;<dfn>Order of Summary Suspension</dfn>&nbsp;is an action in which a judge suspends a license upon the receipt of allegations that the business poses an immediate and substantial threat to health, and prior to a full hearing.&nbsp;<a title=\"Jump back to footnote 1 in the text\" href=\"https://www.ic3.gov/PSA/2025/PSA250228#retfn1\">↩</a></p></footer>', 2025, '2025-02-28', '', '', 1740672000, 1766592055),
(43, 'PSA250226', 'North Korea Responsible for $1.5 Billion Bybit Hack', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is releasing this PSA to advise the Democratic People\'s Republic of Korea (<abbr>North Korea</abbr>) was responsible for the theft of approximately $1.5 billion&nbsp;<abbr title=\"United States Dollars\" style=\"text-decoration: unset;\">USD</abbr>&nbsp;in virtual assets from cryptocurrency exchange, Bybit, on or about February 21, 2025. FBI refers to this specific North Korean malicious cyber activity as \"<a target=\"_blank\" href=\"https://www.ic3.gov/CSA/2022/220418.pdf\">TraderTraitor</a>.\"</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">TraderTraitor actors are proceeding rapidly and have converted some of the stolen assets to Bitcoin and other virtual assets dispersed across thousands of addresses on multiple blockchains. It is expected these assets will be further laundered and eventually converted to fiat currency.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">How You Can Help:</h2><p>FBI encourages private sector entities including&nbsp;<strong>RPC node operators</strong>, exchanges, bridges, blockchain analytics firms, DeFi services, and other virtual asset service providers to block transactions with or derived from addresses TraderTraitor actors are using to launder the stolen assets.</p><p>The following Ethereum addresses are holding or have held assets from the theft, and are operated by or closely connected to North Korean TraderTraitor actors:</p><ul class=\"addresses\" style=\"list-style-type: none; font-variant-numeric: tabular-nums; font-family: monospace; padding-left: 0px;\"><li>0x51E9d833Ecae4E8D9D8Be17300AEE6D3398C135D</li><li>0x96244D83DC15d36847C35209bBDc5bdDE9bEc3D8</li><li>0x83c7678492D623fb98834F0fbcb2E7b7f5Af8950</li><li>0x83Ef5E80faD88288F770152875Ab0bb16641a09E</li><li>0xAF620E6d32B1c67f3396EF5d2F7d7642Dc2e6CE9</li><li>0x3A21F4E6Bbe527D347ca7c157F4233c935779847</li><li>0xfa3FcCCB897079fD83bfBA690E7D47Eb402d6c49</li><li>0xFc926659Dd8808f6e3e0a8d61B20B871F3Fa6465</li><li>0xb172F7e99452446f18FF49A71bfEeCf0873003b4</li><li>0x6d46bd3AfF100f23C194e5312f93507978a6DC91</li><li>0xf0a16603289eAF35F64077Ba3681af41194a1c09</li><li>0x23Db729908137cb60852f2936D2b5c6De0e1c887</li><li>0x40e98FeEEbaD7Ddb0F0534Ccaa617427eA10187e</li><li>0x140c9Ab92347734641b1A7c124ffDeE58c20C3E3</li><li>0x684d4b58Dc32af786BF6D572A792fF7A883428B9</li><li>0xBC3e5e8C10897a81b63933348f53f2e052F89a7E</li><li>0x5Af75eAB6BEC227657fA3E749a8BFd55f02e4b1D</li><li>0xBCA02B395747D62626a65016F2e64A20bd254A39</li><li>0x4C198B3B5F3a4b1Aa706daC73D826c2B795ccd67</li><li>0xCd7eC020121Ead6f99855cbB972dF502dB5bC63a</li><li>0xbdE2Cc5375fa9E0383309A2cA31213f2D6cabcbd</li><li>0xD3C611AeD139107DEC2294032da3913BC26507fb</li><li>0xB72334cB9D0b614D30C4c60e2bd12fF5Ed03c305</li><li>0x8c7235e1A6EeF91b980D0FcA083347FBb7EE1806</li><li>0x1bb0970508316DC735329752a4581E0a4bAbc6B4</li><li>0x1eB27f136BFe7947f80d6ceE3Cf0bfDf92b45e57</li><li>0xCd1a4A457cA8b0931c3BF81Df3CFa227ADBdb6E9</li><li>0x09278b36863bE4cCd3d0c22d643E8062D7a11377</li><li>0x660BfcEa3A5FAF823e8f8bF57dd558db034dea1d</li><li>0xE9bc552fdFa54b30296d95F147e3e0280FF7f7e6</li><li>0x30a822CDD2782D2B2A12a08526452e885978FA1D</li><li>0xB4a862A81aBB2f952FcA4C6f5510962e18c7f1A2</li><li>0x0e8C1E2881F35Ef20343264862A242FB749d6b35</li><li>0x9271EDdda0F0f2bB7b1A0c712bdF8dbD0A38d1Ab</li><li>0xe69753Ddfbedbd249E703EB374452E78dae1ae49</li><li>0x2290937A4498C96eFfb87b8371a33D108F8D433f</li><li>0x959c4CA19c4532C97A657D82d97acCBAb70e6fb4</li><li>0x52207Ec7B1b43AA5DB116931a904371ae2C1619e</li><li>0x9eF42873Ae015AA3da0c4354AeF94a18D2B3407b</li><li>0x1542368a03ad1f03d96D51B414f4738961Cf4443</li><li>0x21032176B43d9f7E9410fB37290a78f4fEd6044C</li><li>0xA4B2Fd68593B6F34E51cB9eDB66E71c1B4Ab449e</li><li>0x55CCa2f5eB07907696afe4b9Db5102bcE5feB734</li><li>0xA5A023E052243b7cce34Cbd4ba20180e8Dea6Ad6</li><li>0xdD90071D52F20e85c89802e5Dc1eC0A7B6475f92</li><li>0x1512fcb09463A61862B73ec09B9b354aF1790268</li><li>0xF302572594a68aA8F951faE64ED3aE7DA41c72Be</li><li>0x723a7084028421994d4a7829108D63aB44658315</li><li>0xf03AfB1c6A11A7E370920ad42e6eE735dBedF0b1</li><li>0xEB0bAA3A556586192590CAD296b1e48dF62a8549</li><li>0xD5b58Cf7813c1eDC412367b97876bD400ea5c489</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Reporting</h2><p>FBI maintains its commitment to protecting the virtual asset community by identifying, mitigating, and disrupting North Korea\'s illicit cybercrime and virtual asset theft activities. If you have any information to provide, please contact&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">your local FBI field office</a>&nbsp;or FBI\'s Internet Crime Complaint Center at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">ic3.gov</a>.</p></section>', 2025, '2025-02-26', '', '', 1740499200, 1766592237),
(44, 'PSA250127', 'Mail Theft-Related Check Fraud is on the Rise', '<main id=\"main\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The FBI and&nbsp;<abbr title=\"United States Postal Inspection Service\" style=\"text-decoration-line: none; text-decoration-style: initial;\">USPIS</abbr>&nbsp;are warning that check fraud is on the rise, with a significant volume enabled through mail theft. Suspicious Activity Reports related to check fraud have nearly doubled from 2021 to 2023.<sup id=\"retfn1\"><a aria-label=\"footnote\" href=\"https://www.ic3.gov/PSA/2025/PSA250127#fn1\">1</a></sup>&nbsp;Fraudsters take advantage of regulations requiring financial institutions to make check funds available within specified timeframes, which is often too short a window for the consumer or financial institutions to identify and stop the fraud. As a result, the compromised checks clear, and the funds are withdrawn by the criminal participants before the fraud is detected.</p><section><h2 style=\"font-size: large; text-transform: uppercase;\">Obtaining the Checks</h2><p>Fraudsters gain access to legitimate checks and sensitive financial data by stealing mailed checks from&nbsp;<abbr title=\"United States Postal Service\" style=\"text-decoration-line: none; text-decoration-style: initial;\">USPS</abbr>&nbsp;facilities or during delivery to the intended recipient. Check theft occurs several ways.</p><picture><source srcset=\"/img/PSA/2025/250127-1.webp\" type=\"image/webp\"><img src=\"https://www.ic3.gov/img/PSA/2025/250127-1.png\" alt=\"Five mechanisms used to obtain checks fraudulently. 1) Checks left in residential mailboxes overnight or for long periods of time. 2) USPS blue collection boxes after the last pickup time. 3) Burglary of USPS facilities. 4) Robbery of USPS employees. 5) Bribery/collusion of USPS employees.\" style=\"max-width: 100%; height: auto; display: block; margin: 0.5em auto;\"></picture></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Preparing/Altering the Checks for Deposit</h2><p>To make the checks appear legitimate, fraudsters use check washing or other check \"cooking\" techniques to alter checks or create counterfeits. In other instances, checks are unaltered and deposited with forged endorsements.</p><div class=\"check-alter\" style=\"display: flex; align-items: center;\"><picture style=\"margin: 0px 0.5rem 0px 0px; flex-shrink: 0;\"><source srcset=\"/img/PSA/2025/250127-2.webp\" type=\"image/webp\"><img src=\"https://www.ic3.gov/img/PSA/2025/250127-2.png\" alt=\"\" style=\"max-width: 100%; height: auto; display: block; margin: 0.5em auto;\"></picture><p><dfn style=\"font-weight: bold;\">Check washing</dfn>&nbsp;involves the use of chemicals to physically alter the check, typically altering the original payee and financial amount.</p></div><div class=\"check-alter\" style=\"display: flex; align-items: center;\"><picture style=\"margin: 0px 0.5rem 0px 0px; flex-shrink: 0;\"><source srcset=\"/img/PSA/2025/250127-3.webp\" type=\"image/webp\"><img src=\"https://www.ic3.gov/img/PSA/2025/250127-3.png\" alt=\"\" style=\"max-width: 100%; height: auto; display: block; margin: 0.5em auto;\"></picture><p><dfn style=\"font-weight: bold;\">Check cooking</dfn>&nbsp;involves the digital manipulation of an image of a stolen check. Using readily available photo editing software and high-tech printers, fraudsters can manufacture checks. Check cooking allows fraudsters to manufacture multiple checks from a single check image. Often these checks are written for smaller amounts which can go undetected for longer periods of time by escaping the scrutiny or visibility of a larger check amount.</p></div></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Depositing the Checks</h2><p>Stolen checks are deposited, often by a collusive account holder who is recruited by the fraudster or sold online for a fraction of the face value to other criminal actors who deposit the checks. In many cases, financial institutions, consumers, and law enforcement agencies are not aware of the fraudulent activity until after funds have been illicitly withdrawn.</p></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">Who is Harmed by Check Fraud?</h2><dl class=\"check-fraud-victims\"><dt style=\"display: inline;\">Businesses</dt>&nbsp;<dd style=\"margin: unset; display: inline;\">Businesses could experience disruption to business activities and reputational harm due to overdue or missed payments or delays or disruption in finalizing payments when account details are compromised.</dd><dt style=\"display: inline;\">Consumers</dt>&nbsp;<dd style=\"margin: unset; display: inline;\">Consumers can experience impacted credit scores for late payments for bills, account closures, stop payment fees for other outstanding checks, missed interest from refund checks, compromised personally identifiable information (<abbr>PII</abbr>) which may also be sold in subsequent fraud schemes, and loss of assets or investment money. Victims of fraud are often refunded some of the charges, but refunds are often delayed until investigations are complete.</dd><dt style=\"display: inline;\">Government Entities</dt>&nbsp;<dd style=\"margin: unset; display: inline;\">Funds intended for citizens are intercepted and altered or forged, resulting in government funds being dispersed incorrectly. It can be a time intensive process to investigate and reissue payments to the rightful recipients of intercepted checks.</dd></dl></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">How to Protect Your Mail</h2><ul class=\"checklist\" style=\"list-style-type: &quot;✓&quot;; padding-left: 0.7rem;\"><li style=\"padding-left: 0.5rem;\">Pick up your mail promptly after delivery. Do not leave mail in your mailbox overnight or for long periods of time.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">If you are heading out of town, submit a&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/holdmail.usps.com/443/holdmail%E2%81%84/B7825AD5A7BF502027353199DF0624A529DCD55EDC1C8E80B5349B33EE0531C0\">USPS Hold Mail</a>™ request asking your local Post Office to hold your mail until you return.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Sign up for&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/informeddelivery.usps.com/443/B40936A96DA1D5CE0FE6E37668EB3B6DC36D9BA5ECF00FB0EF40E3ECBF76858F\">Informed Delivery</a><sup>®</sup>&nbsp;at USPS.com to receive daily email notifications of incoming mail and packages.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Contact the sender if you do not receive a check, credit card or other valuable mail you are expecting.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Consider buying and using security envelopes to conceal the contents of your mail.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Use the letter slots inside your local Post Office to send mail. If using a blue USPS collection box, be sure to drop your mail as close to the posted pickup time as possible and before the last collection of the day.</li></ul></section><section><h2 style=\"font-size: large; text-transform: uppercase;\">How to Protect Your Checks</h2><ul class=\"checklist\" style=\"list-style-type: &quot;✓&quot;; padding-left: 0.7rem;\"><li style=\"padding-left: 0.5rem;\">Use pens with indelible black ink so it is more difficult for a criminal to wash your checks.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Don\'t leave blank spaces in the payee or amount lines.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Don\'t write personal details, such as your Social Security number, credit card information, driver\'s license number, or phone number on checks.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Use mobile or online banking to access copies of your checks and ensure they are not altered. While logged in, review your bank activity and statements for errors.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Consider using e-check,&nbsp;<abbr title=\"Automated Clearing House\" style=\"text-decoration-line: none; text-decoration-style: initial;\">ACH</abbr>&nbsp;automatic payments, and other electronic and/or mobile payments.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Follow up with payees to make sure they received your check.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Use check positive pay if available at financial institutions to help detect and stop fraudulent checks.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Use checks with security features to limit the effectiveness of check washing. Security features can include microprinting, holograms, heat-sensitive ink, watermarks, toner adhesion, chemically reactive paper, security screens, thermal thumbprints, void pantographs, ultraviolet overprinting, security padlock icon, and fraud warnings.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">If you believe you have been defrauded, contact your bank immediately. Consider opening a new account and closing out the compromised account to prevent future counterfeit checks being drawn off the account.</li><li style=\"padding-left: 0.5rem; margin-top: 0.5rem;\">Protect vulnerable members of your family and community. Fraudsters use high-tech, low-cost technology including printers, call spoofing technology, and AI-assisted voice recreation to fool vulnerable people into acting as unwitting accomplices.</li></ul></section><p>If you think you were targeted by fraud, file a report with your bank and request copies of all fraudulent checks. Report the incident to the FBI Internet Crime Complaint Center (<abbr>IC3</abbr>),&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. If you believe you are the victim of mail theft-related check fraud, report to your local police and the United States Postal Inspection Service at&nbsp;<a target=\"_blank\" href=\"https://www.uspis.gov/report\">uspis.gov/report</a>&nbsp;or&nbsp;<a href=\"tel:+1(877)876-2455\">1-877-876-2455</a>.</p></main><hr class=\"before-footnote\" style=\"margin: 0px 24px; width: 312px; background-color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><footer class=\"footnotes\" style=\"margin: 0px 24px; color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p id=\"fn1\"><sup>1</sup>&nbsp;<cite>SAR Filings by Industry | Filing Trend Data: Depository Institution | Exhibit 5: Number of Filings by Type of Suspicious Activity from Depository Institution Industry | Between 01 January 2014 and 31 December 2023</cite>&nbsp;|&nbsp;<a target=\"_blank\" href=\"https://www.fincen.gov/reports/sar-stats/sar-filings-industry\">https://www.fincen.gov/reports/sar-stats/sar-filings-industry</a>&nbsp;| Accessed 18 December 2024.&nbsp;<a title=\"Jump back to footnote 1 in the text\" href=\"https://www.ic3.gov/PSA/2025/PSA250127#retfn1\">↩</a></p></footer>', 2025, '2025-01-27', '', '', 1737907200, 1766600638),
(45, 'PSA250123', 'North Korean IT Workers Conducting Data Extortion', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The Federal Bureau of Investigation (<abbr>FBI</abbr>) is providing an update to previously shared guidance regarding Democratic People\'s Republic of Korea (<abbr>North Korea</abbr>) Information Technology (<abbr>IT</abbr>) workers to raise public awareness of their increasingly malicious activity, which has recently included data extortion. FBI is warning the public, private sector, and international community about North Korean IT workers\' continued victimization of US-based businesses. In recent months, in addition to data extortion, FBI has observed North Korean IT workers leveraging unlawful access to company networks to exfiltrate proprietary and sensitive data, facilitate cyber-criminal activities, and conduct revenue-generating activity on behalf of the regime.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h3 style=\"font-size: medium;\">Extortion and Theft of Sensitive Company Data</h3><ul><li>After being discovered on company networks, North Korean IT workers have extorted victims by holding stolen proprietary data and code hostage until the companies meet ransom demands. In some instances, North Korean IT workers have publicly released victim companies\' proprietary code.</li><li style=\"margin-top: 1rem;\">North Korean IT workers have copied company code repositories, such as GitHub, to their own user profiles and personal cloud accounts. While not uncommon among software developers, this activity represents a large-scale risk of theft of company code.</li><li style=\"margin-top: 1rem;\">North Korean IT workers could attempt to harvest sensitive company credentials and session cookies to initiate work sessions from non-company devices and for further compromise opportunities.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Your Business</h2><section><h3 style=\"font-size: medium;\">Recommendations for Data Monitoring</h3><ul><li>Practice the Principle of Least Privilege on your networks, to include disabling local administrator accounts and limiting privileges for installing remote desktop applications.</li><li style=\"margin-top: 1rem;\">Monitor and investigate unusual network traffic, to include remote connections to devices or the installation/presence of prohibited remote desktop protocols or software. North Korean IT workers often have multiple logins into one account in a short period of time from various IP addresses, often associated with different countries.</li><li style=\"margin-top: 1rem;\">Monitor network logs and browser session activity to identify data exfiltration through easily accessible means such as shared drives, cloud accounts, and private code repositories.</li><li style=\"margin-top: 1rem;\">Monitor endpoints for the use of software that allows for multiple audio/video calls to take place concurrently.</li></ul></section><section><h3 style=\"font-size: medium;\">Recommendations for Strengthening Remote-Hiring Processes</h3><ul><li>Implement identity-verification processes during interviewing, onboarding, and throughout the employment of any remote worker. Cross-check HR systems for other applicants with the same resume content and/or contact information. North Korean IT workers have been observed using artificial intelligence and face-swapping technology during video job interviews to obfuscate their true identities.</li><li style=\"margin-top: 1rem;\">Educate&nbsp;<abbr title=\"Human Resources\" style=\"text-decoration: unset;\">HR</abbr>&nbsp;staff, hiring managers, and development teams regarding the North Korean IT worker threat, specifically focusing on changes in address or payment platforms during the onboarding process.</li><li style=\"margin-top: 1rem;\">Review each applicant\'s communication accounts as North Korean IT workers have reused phone numbers (particularly voice-over-IP numbers) and email addresses, on multiple resumes purportedly belonging to different applicants.</li><li style=\"margin-top: 1rem;\">Verify third-party staffing firms conduct robust hiring practices and routinely audit those practices.</li><li style=\"margin-top: 1rem;\">Use \"soft\" interview questions to ask applicants for specific details about their location or education background. North Korean IT workers often claim to have attended non-US educational institutions.</li><li style=\"margin-top: 1rem;\">Check applicant resumes for typos and unusual nomenclature.</li><li style=\"margin-top: 1rem;\">Complete as much of the hiring and onboarding process as possible in person.</li></ul></section></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Reporting</h2><p>If you suspect you have been approached or victimized by a North Korean IT worker, FBI recommends taking the following actions:</p><ul><li>Report the suspicious activity to the FBI\'s Internet Crime Complaint Center (<abbr>IC3</abbr>) at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.IC3.gov</a>&nbsp;as quickly as possible.</li><li style=\"margin-top: 1rem;\">Evaluate network activity from the suspected employee and their assigned device(s), and use internal intrusion-detection software to capture activity on the suspected device(s).</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Reference</h2><p>In&nbsp;<a target=\"_blank\" href=\"https://ofac.treasury.gov/media/923126/download?inline\">2022</a>&nbsp;and&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2023/PSA231018\">2023</a>, the United States, along with foreign partners, issued public advisories regarding how North Korean IT workers operate and provided red-flag indicators and due-diligence measures for businesses to avoid hiring North Korean freelance developers. In&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2024/PSA240516\">May 2024</a>, FBI provided further guidance regarding North Korean IT workers and their use of witting and unwitting US-based individuals.</p></section>', 2025, '2025-01-23', '', '', 1737561600, 1766600686),
(46, 'PSA250116', 'Beware of Charitable Fraud Related to Mass Casualty and Disaster Events', '<p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">The FBI is issuing this Public Service Announcement to warn the public that scammers exploit mass casualty events and disasters, such as the New Year\'s Day terrorist attack in New Orleans and the ongoing wildfires in Los Angeles, to commit fraud by soliciting fake charitable donations to support victims or their families. Scammers may pose as disaster relief agencies to collect personal information, conduct charitable fraud schemes, or commit fraud against disaster assistance programs. Scammers may also impersonate official entities, celebrities, influencers, or other individuals. For example, a scammer might pose online as a high-profile victim to solicit donations. Artificial Intelligence (<abbr>AI</abbr>) may be used to increase perceived legitimacy of a fraud or impersonation.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">Criminals have used past crises as opportunities to target members of the public with fraudulent donation schemes. Scammers take advantage of catastrophic incidents — such as mass casualty events, terrorist attacks, war, natural disasters, or pandemics — to pose as charitable entities providing humanitarian aid or developing fundraising efforts, including monetary and cryptocurrency donations. Charitable fraud schemes associated with natural disasters are a common occurrence online as well as through in-person collection drives.</p><p style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\">In 2024, the FBI Internet Crime Complaint Center (IC3) received more than 4,500 complaints reporting approximately $96 million in losses to fraudulent charities, crowdfunding accounts, and disaster relief campaigns.</p><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Tips to Protect Yourself</h2><ul><li><p>Do your own research before you donate to anything. Confirm the validity of any charitable opportunity. Best practices include, but are not limited to:</p><ul><li>Verifying charities by researching the charity online to see if there are news articles, reviews, or posts linking the charity to fraud; checking to see if the charity is registered with your state\'s charity regulator, if available; and checking the Internal Revenue Service\'s website (<a target=\"_blank\" href=\"https://www.irs.gov/\">https://www.irs.gov</a>) to see if the charity is registered.</li><li style=\"margin-top: 1rem;\">Validating that crowdfunding efforts are supporting the beneficiaries advertised; researching who is behind the crowdfunding request; researching who the request is intended to benefit and if the need is legitimate; and reverse searching images and stories associated with the request, as scammers will often copy and paste material stolen from others.</li></ul></li><li style=\"margin-top: 1rem;\">Be suspicious of online communications claiming to be from individuals affected by the events and seeking immediate financial assistance.</li><li style=\"margin-top: 1rem;\">Recognize that pressure to \"act fast\" might be a sign of a scam.</li><li style=\"margin-top: 1rem;\">Do not send payments to unknown individuals or organizations asking for financial assistance.</li><li style=\"margin-top: 1rem;\">Do not communicate with or open texts, posts, emails, attachments, or links from unknown individuals posing as entities soliciting charitable donations or humanitarian aid.</li><li style=\"margin-top: 1rem;\">Review email headers and domain information to evaluate legitimacy. Emails from official organizations almost never will come from free email services. IP addresses can reveal if the information is originating from overseas. Domain names and IP addresses\' current registration information may be available through the registry at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Egress/https/lookup.icann.org/443/3CCCB3F6148862E1F996D5E54F5578AA00ABAAFB4197E05744BB596B0183F206\">lookup.ICANN.org</a>&nbsp;if it was not restricted by the domain or IP address owner.</li><li style=\"margin-top: 1rem;\">If an unknown individual contacts you, do not release any financial or personal identifying information (<abbr>PII</abbr>), and do not send any money.</li><li style=\"margin-top: 1rem;\">If you have already donated funds and believe you are a victim of a scheme, do not pay additional fees or taxes to obtain a refund of your money. Do not pay for any services that claim they can recover lost funds.</li><li style=\"margin-top: 1rem;\">Do not use debit, gift, or prepaid cards for payment.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Report It</h2><p>If you believe you have been a victim of a financial internet scam or a fraudulent scheme related to the New Year\'s Day or other mass casualty events, please file a report with the FBI\'s IC3 at&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/\">www.ic3.gov</a>. If possible, include the following:</p><ul><li>Identifying information about the individuals or charity, including name, phone number, address, email addresses, social media handles, etc.</li><li style=\"margin-top: 1rem;\">Financial transaction information, such as the date, type of payment, amount, account numbers involved, name and address of the receiving financial institution, and receiving cryptocurrency addresses.</li><li style=\"margin-top: 1rem;\">Describe your interaction with the individual, including how contact was initiated, such as the type of communication, purpose of the request for money, how you were told or instructed to make payment, what information you provided to the criminal actor, and any other details pertinent to your complaint.</li></ul></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Additional Resources</h2><ul><li>FBI.gov:&nbsp;<a target=\"_blank\" href=\"https://www.fbi.gov/how-we-can-help-you/scams-and-safety/common-frauds-and-scams/charity-and-disaster-fraud\">Charity and Disaster Fraud</a></li><li style=\"margin-top: 1rem;\">IC3 PSA:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2023/PSA231024\">Scammers Solicit Fake Humanitarian Donations</a>&nbsp;<time datetime=\"2023-10-24T14:00:00.000-04:00\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: unset;\">October 23, 2023</time></li><li style=\"margin-top: 1rem;\">IC3 PSA:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2022/PSA220531\">The FBI Warns of Scammers Soliciting Donations Related to the Crisis in Ukraine</a>&nbsp;<time datetime=\"2022-05-31T14:00:00.000-04:00\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: unset;\">May 31, 2022</time></li><li style=\"margin-top: 1rem;\">IC3 PSA:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/PSA/2020/PSA200320\">FBI Sees Rise in Fraud Schemes Related to the Coronavirus (COVID-19) Pandemic</a>&nbsp;<time datetime=\"2020-03-20T10:20:00.000-04:00\" style=\"font-weight: unset; font-size: unset; margin: unset; text-align: unset;\">March 20, 2020</time></li><li style=\"margin-top: 1rem;\">IC3:&nbsp;<a target=\"_blank\" href=\"https://www.ic3.gov/Outreach/Resources\">Victim Resource Information</a></li></ul></section>', 2025, '2025-01-16', '', '', 1736956800, 1766600725),
(47, 'PSA250113', 'Threat of Copycat Attacks after ISIS-Inspired Vehicle Attack in New Orleans', '<section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><p>The Federal Bureau of Investigation (<abbr>FBI</abbr>) and Department of Homeland Security (<abbr>DHS</abbr>) are issuing this Public Service Announcement to highlight a potential public safety threat from violent extremists in response to the New Year’s Day attack in New Orleans, Louisiana. As with any potential threats to the United States, we will coordinate with our state and local law enforcement partners to ensure they have the resources and information necessary to keep our communities safe.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Threat</h2><p>The FBI and DHS are concerned about possible copycat or retaliatory attacks due to the persistent appeal of vehicle ramming as a tactic for aspiring violent extremist attackers. Previous attackers inspired by foreign terrorist organizations (<abbr>FTO</abbr>s) who have conducted vehicle attacks in the United States and abroad have used rented, stolen, and personally owned vehicles, which are easy to acquire. Some have used additional weapons, such as firearms and knives, to attack individuals after the vehicle has stopped. Additionally, attackers may attempt to conceal and pre-position improvised explosive devices (<abbr>IED</abbr>s) to supplement a vehicle attack. Targets have included pedestrians, law enforcement or military members, and crowded public venues, including festivals and commercial centers, which generally are accessible from roadways. We ask that the public remain vigilant regarding possible copycat or retaliatory attacks and report any suspicious activity to law enforcement.</p></section><section style=\"color: rgb(0, 0, 0); font-family: verdana, arial, helvetica, sans-serif; font-size: medium;\"><h2 style=\"font-size: large; text-transform: uppercase;\">Resources</h2><ul class=\"list-paragraphs\" style=\"list-style-type: none; padding-left: 0px;\"><li>The FBI and DHS encourage the public to promptly report information concerning suspicious activity to tips.fbi.gov or contact their local FBI field office (<a target=\"_blank\" href=\"https://www.fbi.gov/contact-us/field-offices\">www.fbi.gov /contact-us/field-offices</a>). Call 911 to report emergencies, including imminent threats to life.</li><li style=\"margin-top: 1rem;\">For concerns involving US citizens abroad, to include reporting missing persons or individuals taken as hostages, please call the Department of State\'s Overseas Citizens Services (<abbr>OCS</abbr>) toll-free hotline at&nbsp;<a href=\"tel:+1(888)407-4747\">(888) 407-4747</a>&nbsp;or complete Crisis Intake Form at&nbsp;<a target=\"_blank\" href=\"https://cacms.state.gov/s/crisis-intake\">https://cacms.state.gov/s/crisis-intake</a>.</li><li style=\"margin-top: 1rem;\">To help mitigate potential risks from a variety of threat actors, DHS, the FBI, and the National Counterterrorism Center have compiled&nbsp;<a target=\"_blank\" href=\"https://www.dhs.gov/prevention\">resources</a>&nbsp;for law enforcement officers, other first responders,&nbsp;<a target=\"_blank\" href=\"https://www.cisa.gov/topics/physical-security/protecting-houses-worship\">faith leaders</a>, and communities, including a&nbsp;<a target=\"_blank\" href=\"https://www.dhs.gov/publication/targeted-violence-and-terrorism-prevention-partner-resource-guide\">list</a>&nbsp;of funding opportunities, resources for technical assistance, and educational materials.</li><li style=\"margin-top: 1rem;\"><ul style=\"list-style-type: disc; padding-left: 1rem;\"><li>Due to the highly personal nature of radicalization to violence and mobilization to violence, it can be difficult to assess specific characteristics indicating the intent of US-based violent extremists to conduct violence. The FBI and DHS urge bystanders to promptly report suspicious activities potentially related to violent extremist activity, including indications of possible online radicalization to violence and mobilization for attacks.</li><li style=\"margin-top: 1rem;\">DHS, the FBI, and NCTC direct public safety partners to the unclassified booklet \"<a target=\"_blank\" href=\"https://www.dni.gov/index.php/nctc-newsroom/nctc-resources/3590-u-s-violent-extremist-mobilization-indicators-2021\">US Violent Extremist Mobilization Indicators 2021 Edition</a>,\" which includes possible indicators of mobilization to violence. These indicators apply to all ideologically motivated, US-based violent extremists. DHS also has developed several unclassified resources for communities to help promote bystander awareness of&nbsp;<a target=\"_blank\" href=\"https://www.dhs.gov/publication/behavioral-approach-violence-prevention\">potentially threatening or concerning behaviors</a>&nbsp;that are observable to others and enhance the capacity to identify and mitigate threats through behavioral threat assessment and management, including publicly available&nbsp;<a target=\"_blank\" href=\"https://www.dhs.gov/foundations-targeted-violence-prevention\">training</a>&nbsp;and&nbsp;<a target=\"_blank\" href=\"https://www.dhs.gov/publication/enhancing-behavioral-threat-assessment-and-case-management-capabilities\">prevention guides</a>.</li></ul></li></ul></section>', 2025, '2025-01-13', '', '', 1736697600, 1766600766);
